"use client";

import type { ComponentProps, CSSProperties } from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "../lib/utils";
import { BAR_SIZE_TO_BADGE_SIZE, useBarSize } from "./barSize";

/**
 * src/components/badge.tsx — a plain, stock shadcn Badge. Not vendored
 * anywhere else in this repo (checked apps/docs and packages/inspector —
 * absent from both), so this is written fresh rather than ported; it's a
 * small, extremely standard shadcn primitive with nothing repo-specific to
 * preserve. No `asChild`/Slot support — this app has no reason yet to
 * render a Badge as a link, and skipping it avoids a new dependency.
 *
 * WHY `size` was added here (stock shadcn's Badge has none): the Bar size
 * cascade (barSize.tsx) needs somewhere to land on Badge, and there was no
 * existing scale to hook into. Four rungs, matching `Bar`'s own directly.
 *
 * WHY `shape` defaults to `"rounded"` rather than flipping to pill
 * (docs/FEEDBACK-2026-09-17b-PLAN.md A-1, Zach: "show some badges with a
 * more pill shape"): he asked to *see* the pill option, not replace the
 * landed look — every existing caller (in particular `Bar`'s title badge,
 * which reads as a chip on purpose) must render unchanged. `rounded-full`
 * is opt-in via `shape="pill"`, not the new floor.
 */
const badgeVariants = cva(
  "relative inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border font-medium whitespace-nowrap transition-[color,box-shadow] [&>svg]:pointer-events-none",
  {
    variants: {
      variant: {
        default: "border-transparent bg-primary text-primary-foreground",
        secondary: "border-transparent bg-secondary text-secondary-foreground",
        destructive: "border-transparent bg-destructive text-white dark:bg-destructive/60",
        // docs/INVALID-STATES-PLAN.md §5's Badge row: "amber bg, dark
        // text" — one cva row, no new component. `--bbox-warning` (ported
        // in src/globals.css) stays light enough in BOTH themes that black
        // text keeps its contrast; `destructive` above needs the opposite
        // (white-on-dark-red) for the same reason.
        warning: "border-transparent bg-[var(--bbox-warning)] text-black",
        // The one variant with a REAL (non-transparent) border, so it's
        // the one that gets `--bbox-skin-line-override`: default/secondary/
        // destructive are already `border-transparent` and need nothing —
        // suppressing an already-invisible border would be a no-op. See
        // block.tsx's own line-override note on why the colour a skin
        // suppresses has to be the one the STATE cascade already owns.
        outline: "border-[color:var(--bbox-skin-line-override,currentColor)] text-foreground",
      },
      size: {
        sm: "gap-0.5 px-1.5 py-0 text-[0.65rem] [&>svg]:size-2.5",
        md: "gap-1 px-2 py-0.5 text-xs [&>svg]:size-3",
        lg: "gap-1 px-2.5 py-1 text-sm [&>svg]:size-3.5",
        xl: "gap-1.5 px-3 py-1 text-base [&>svg]:size-4",
      },
      // WHY radius moved OFF these two classes and onto inline style
      // (see the component body): `rounded-md`/`rounded-full` bake a
      // fixed radius no skin token can reach. The literal each falls back
      // to below is unchanged from before this port — `rounded-md` here
      // resolves to `var(--radius-md)` = 8px on this app's `--radius:
      // 0.625rem` base, captured live off `components-text-marks-badge--variants` before
      // the edit.
      shape: {
        rounded: "",
        pill: "",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "md",
      shape: "rounded",
    },
  },
);

export interface BadgeProps extends ComponentProps<"span">, VariantProps<typeof badgeVariants> {}

export function Badge({ className, variant, size, shape, style, ...props }: BadgeProps) {
  // Explicit `size` wins; the ambient Bar cascade is only the fallback when
  // `size` itself is omitted, `"md"` (cva's own default) is the floor when
  // there is no Bar ancestor either.
  const barSize = useBarSize();
  const resolvedSize = size ?? (barSize && BAR_SIZE_TO_BADGE_SIZE[barSize]) ?? "md";
  const resolvedShape = shape ?? "rounded";
  return (
    <span
      data-slot="badge"
      data-size={resolvedSize}
      data-shape={resolvedShape}
      // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M7. The edge has
      // no props, so its default seed is geometry-derived
      // (`${width}x${height}`) — a different wobble PATTERN than this
      // component's own semantic seed, `badge:${resolvedSize}:${resolvedShape}`
      // (same character and amplitude either way, just a different jitter
      // sequence). Publishing it closes that gap: `sketchAtEdge.ts`'s
      // `seedForBox` reads this attribute first.
      data-bbox-seed={`badge:${resolvedSize}:${resolvedShape}`}
      className={cn(badgeVariants({ variant, size: resolvedSize, shape: resolvedShape }), className)}
      style={{
        borderRadius:
          resolvedShape === "pill"
            ? "var(--bbox-skin-radius-pill, 9999px)"
            : "var(--bbox-skin-radius, var(--radius-md))",
        // WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M6.
        // `currentColor` IS this variant's resolved line colour — every
        // variant above sets its own `text-*` class, and a real CSS border
        // (the `outline` variant) is already drawn in `currentColor`. A
        // boundary twin is appended as a CHILD of this span, so it inherits
        // the same `color` and lands on the same value without this
        // component importing the skin or hardcoding a token.
        ...({ "--bbox-ink-state": "currentColor" } as CSSProperties),
        ...style,
      }}
      {...props}
    >
      {props.children}
    </span>
  );
}

export { badgeVariants };

import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import { BarSizeProvider } from "./barSize";

/**
 * Bar — a horizontal strip with three slots (left · center · right).
 * Structure is unchanged from the reset: no appearance cascade, no
 * tone/state, just the three slots. What changed in the shadcn/Tailwind
 * migration is HOW it's painted — Tailwind utilities against the shadcn CSS
 * variables in src/globals.css instead of raw `style={{...}}` colors,
 * borrowing the visual vocabulary (not the props) of
 * packages/bbox-ui/src/bar.tsx.
 *
 * WHY the grid template is COMPUTED, not a fixed `1fr auto 1fr` (Zach: "if
 * the center slot is empty or so, then things in the other slots should
 * just continue to expand width wise, and not truncate. Unless you
 * specifically set a width limit"): `1fr auto 1fr` forces the left/right
 * tracks to stay EQUAL width even when one of them (or center) is empty —
 * that symmetry is exactly what real centering needs, but it also means an
 * empty center/right still claims (and wastes) half the bar's width, and a
 * long `left` label truncates against that artificial half-width ceiling
 * with the other half sitting empty. Measured live: a previous lane's own
 * `AllSizes` cascade cluster had already been moved from `left` to `center`
 * and its swatch widened 420→520px specifically to dodge this — a symptom
 * fix, not a cause fix, and reverted below now that the cause is fixed.
 * `barGridTemplateColumns` (below) keeps `1fr auto 1fr`'s symmetric flanks
 * ONLY when `center` actually holds content (centering is structurally
 * impossible without equal flanks, filled or not); otherwise the unused
 * slot's track collapses to `0` and `left`'s own track becomes the single
 * `1fr` that absorbs everything center/right aren't using — so it only
 * truncates once the BAR ITSELF is out of room, never before. A caller that
 * wants a truncation limit narrower than "however wide the bar naturally
 * is" sets one explicitly by wrapping its own content in a `width`-bounded
 * box — see `Bar.stories.tsx`'s `Widths` gallery — rather than `Bar`
 * growing a new prop for it.
 *
 * WHY no `rounded-lg`/`border`/`bg-card` here: a Bar is a layout strip, not
 * a card — the same way `Flex` paints nothing of its own. Zach: "I don't
 * like how the bars have these borders. they should fill the block footer
 * and headers edge to edge... the only lines are the dividers." A Bar
 * filling `Block`'s header/footer must read as flush with it, not as a
 * pill floating inside it — `Block`'s own `border-b`/`border-t` supply the
 * only lines. A standalone Bar story that wants to show the strip's own
 * extent adds a wrapper (e.g. a dashed box) at the STORY level instead.
 *
 * WHY `size` is also published via `BarSizeProvider`: Zach's size-cascade
 * ask — a Bar's contents should size themselves off the Bar's own `size`
 * rather than each getting hand-tuned. See `barSize.tsx` for the mapping
 * from these four rungs onto each consumer's own scale.
 */
function barGridTemplateColumns(hasCenter: boolean, hasRight: boolean): string {
  if (hasCenter) return "1fr auto 1fr";
  if (hasRight) return "1fr 0 auto";
  return "1fr 0 0";
}

export const BAR_SIZES = ["sm", "md", "lg", "xl"] as const;
export type BarSize = (typeof BAR_SIZES)[number];

/** Bar height per rung, px. */
export const BAR_HEIGHT: Record<BarSize, number> = { sm: 28, md: 36, lg: 48, xl: 60 };

export interface BarProps {
  left?: ReactNode;
  center?: ReactNode;
  right?: ReactNode;
  size?: BarSize;
  style?: CSSProperties;
}

// WHY `overflow-clip` + a 4px `overflow-clip-margin` instead of plain
// `overflow-hidden`: a focusable control flush against a cell's edge (a
// left-slot FoldingChevron, a right-slot Toggle/Button) paints its
// focus-visible ring OUTSIDE its own border box — `hidden` clips that ink
// the instant it crosses the cell boundary, which is the actual cause of
// the bug Zach reported ("chevron has a box cut off on its left") and,
// measured live, hits any focusable control sitting flush at a cell edge,
// not just the chevron. `overflow-clip-margin` is the CSS-spec-native fix:
// it only relaxes where PAINT (ink like a box-shadow ring or an outline) is
// allowed to bleed past the clip box, layout overflow — the thing this
// class exists to contain, e.g. EditableText's own `minWidth:0`/ellipsis
// truncation still clips flush at (edge + 4px). 4px covers both the
// shadcn ring-3 box-shadow (3px spread, 0 offset) and the browser's native
// default outline that a bare-button control like FoldingChevron falls
// back to. Only takes effect on `overflow: clip` (not `hidden`), which is
// otherwise behaviourally identical for this cell's purposes — no scroll
// either way.
const cellClass = "flex min-w-0 items-center overflow-clip [overflow-clip-margin:4px]";

export function Bar({ left, center, right, size = "md", style }: BarProps) {
  return (
    <BarSizeProvider size={size}>
      <div
        data-slot="bar"
        data-size={size}
        // WHY `group`: a plain Tailwind marker class, paints nothing on its
        // own — it exists so a `FoldingChevron reveal="hover"` inside this
        // Bar can key its `group-hover`/`group-focus-within` reveal off the
        // Bar itself ("the surrounding region... the Bar/header it lives
        // in", not the 24px button). Harmless for every Bar that has no
        // such child.
        className={cn("group grid w-full items-center gap-2 px-3 text-sm text-card-foreground")}
        style={{
          gridTemplateColumns: barGridTemplateColumns(center !== undefined, right !== undefined),
          height: BAR_HEIGHT[size],
          ...style,
        }}
      >
        <div data-slot="bar-left" className={cn(cellClass, "justify-start")}>
          {left}
        </div>
        <div data-slot="bar-center" className={cn(cellClass, "justify-center")}>
          {center}
        </div>
        <div data-slot="bar-right" className={cn(cellClass, "justify-end")}>
          {right}
        </div>
      </div>
    </BarSizeProvider>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

import type { BarSize } from "./bar";
import type { EditableTextSize } from "./editableText.layout";
import type { GlyphSize } from "./glyph.layout";

/**
 * src/components/barSize.tsx — the size CASCADE from `Bar` down to its own
 * contents. Zach: "various things inside of the bar will size themselves
 * correctly... with a 'large bar' vs small bar you don't need to hand tune
 * each element inside." A React context, mirroring `glyph.tsx`'s own
 * resolver-context pattern (provider + `use*` hook), not a new prop
 * threaded through every layer in between — `Bar` already owns a `size`
 * prop (bar.tsx); this only makes that value reach descendants.
 *
 * The mapping from Bar's four rungs (sm/md/lg/xl) onto each consumer's OWN
 * size scale lives HERE, in one place, rather than scattered per component.
 * `Glyph`/`EditableText` already share Bar's exact four-rung ladder, so
 * their mapping is the identity — still spelled out below so all five
 * mappings are visible in one lookup. `Badge`/`Button`/`Toggle` each carry
 * a differently-shaped scale of their own.
 *
 * An explicit size prop on any child ALWAYS wins — every consumer only
 * calls into this context as the fallback when its own prop is
 * `undefined`, same "explicit beats derived" rule `glyphFootprint` already
 * applies to its own size/sizePreset pair.
 */

const BarSizeContext = createContext<BarSize | undefined>(undefined);

/** Mounted by `Bar` itself (bar.tsx) — not meant to be reached for by callers. */
export function BarSizeProvider({ size, children }: { size: BarSize; children?: ReactNode }) {
  return <BarSizeContext.Provider value={size}>{children}</BarSizeContext.Provider>;
}

/** `undefined` outside any `Bar` — "not inside a cascade," not an error;
 *  same shape as `useGlyphResolver`'s "no provider mounted" case. */
export function useBarSize(): BarSize | undefined {
  return useContext(BarSizeContext);
}

/** Glyph's own ladder (glyph.layout.ts's `GLYPH_SIZES`) is identical to
 *  Bar's four rungs, so the cascade is the identity. */
export const BAR_SIZE_TO_GLYPH_PRESET: Record<BarSize, GlyphSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** EditableText's own ladder (editableText.layout.ts's `EDITABLE_TEXT_SIZES`)
 *  is the same four-rung ladder too — see that file's own comment on why
 *  Glyph/EditableText/Port each keep an independent ladder rather than
 *  sharing one, even though the VALUES line up. */
export const BAR_SIZE_TO_EDITABLE_TEXT_SIZE: Record<BarSize, EditableTextSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Badge has no size scale of its own yet (badge.tsx was a plain stock
 *  shadcn Badge, one size only) — this cascade is what gives it one,
 *  matching Bar's own four rungs directly. */
export type BadgeSize = "sm" | "md" | "lg" | "xl";
export const BAR_SIZE_TO_BADGE_SIZE: Record<BarSize, BadgeSize> = {
  sm: "sm",
  md: "md",
  lg: "lg",
  xl: "xl",
};

/** Button and Toggle each already ship a THREE-rung size scale
 *  (sm/default/lg — no "xl"), so Bar's `xl` clamps down to their largest
 *  rung rather than this cascade inventing a fourth one they don't have. */
export type ButtonToggleSize = "sm" | "default" | "lg";
export const BAR_SIZE_TO_BUTTON_SIZE: Record<BarSize, ButtonToggleSize> = {
  sm: "sm",
  md: "default",
  lg: "lg",
  xl: "lg",
};
export const BAR_SIZE_TO_TOGGLE_SIZE: Record<BarSize, ButtonToggleSize> = BAR_SIZE_TO_BUTTON_SIZE;

import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";
import {
  DEFAULT_HIGHLIGHTER_KIND,
  DiagnosticFlag,
  DIAGNOSTIC_FLAG_SIZE_PX,
  diagnosticColorVar,
  highlighterMaskFrameStyle,
  highlighterStrokeOutlineStyle,
  maxDiagnosticSeverity,
  type Diagnostic,
  type HighlighterKind,
} from "./highlighter";
import { HIT_REGION_FILL, HIT_REGION_OUTLINE } from "./hitRegion";
import {
  BLOCK_MEMBER_GAP_PX,
  BLOCK_MEMBER_INSET_PX,
  BlockMembers,
  type BlockInsetBackground,
  type BlockMember,
  type BlockMembersLayout,
} from "./blockMembers";
import { BlockDescription, blockDescriptionIsPainted } from "./blockDescription";
import { ISOLATED_ROOT_STYLE, paintTier } from "./paintOrder";

/**
 * Block — header / body / footer, stacked. All three are plain slots: pass
 * text, pass nothing, or pass a <Bar> to compose the two components
 * together (that composition is the point of this reset pass — see
 * src/components/Block.stories.tsx's "ComposedWithBar" story). A slot given
 * `undefined` is omitted entirely, not merely emptied, so a header-less
 * Block draws no stray divider line. Painted with Tailwind + the shadcn CSS
 * variables from src/globals.css.
 *
 * WHY this file imports no port concept, and must keep not doing so (Zach,
 * 2026-09-17, docs/BLOCK-PORT-EDGES-PLAN.md D-A1): Block is usable on its
 * own — a card with a header, a body, a footer — and ports are something
 * "we're starting to add more and more things to", not a fact about every
 * Block. `./blockPort.tsx`'s `BlockPort` is the wrapper that mounts ports on
 * a Block's walls; it composes THIS component from the outside rather than
 * this component growing port props, because Block's own root below is
 * `overflow-hidden` and would clip a rail dot that deliberately straddles
 * the border line. See blockPort.tsx's own header for the reciprocal note.
 *
 * WHY `body` is conditional like the other two, and `height` has no default:
 * Zach's folding-chevron requirement is "make sure that it hides the body and
 * footer when you click it." Body used to render unconditionally and `height`
 * defaulted to 240, so a collapsed Block stayed a 240px box with an empty
 * well under its header — the text vanished but nothing folded (measured:
 * 180px open, 180px closed, body GREW 80px → 125px as the footer left). Both
 * halves are needed: omitting the region is what removes the content, and an
 * absent height is what lets the box hug what remains. That also restores
 * this repo's own stated size contract (ARCHITECTURE.md): "Explicit size when
 * the scene carries one; hug contents when it does not" — a caller that wants
 * a fixed box still passes one.
 *
 * WHY the header/footer wrappers' `px-3 py-2` is cancelled with
 * `has-[>[data-slot=bar]]:p-0` rather than removed outright: Zach's bar
 * feedback wants a Bar filling the header/footer to sit edge-to-edge with
 * the divider — a Bar's OWN `px-3` (bar.tsx) supplies the inset instead, so
 * stacking both paddings would double it back up. A bare string/ReactNode
 * header (no Bar) still needs Block's own padding — it has none of its own
 * — so the wrapper keeps `px-3 py-2` as its default and only zeroes it when
 * a `<Bar>` is the direct child, detected via `data-slot="bar"` rather than
 * a new Block prop.
 */

/**
 * The outline a Block draws — its four corner radii, and nothing else.
 *
 * - `"card"` (default): rounded at all four corners with the skin radius, the
 *   Block every caller has always had.
 * - `"region-corner"`: the Block sitting in a `BlockRegion`'s top-left corner.
 *   Rounded with the region FRAME's radius at the top-left, the corner it
 *   shares with the frame, and at its one free corner, the bottom-right.
 *   SQUARE at the top-right and bottom-left.
 *
 * WHY top-right and bottom-left are square: those two are the JUNCTIONS. The
 * card's top edge continues as the frame's top rule, and its left edge as the
 * frame's left rule. A radius there pulls the card's edge away from the
 * frame's line, so the border kinks twice on its way round. Zach, 2026-09-19,
 * annotating the tldraw app (`Pasted image 20260919180659.png`): "I don't
 * like how the edges where it meets the region are still curve. they shuld be
 * straight!" WHAT THIS REJECTS: the all-round `card`, the tempting default
 * because every other Block on the board wears it. It makes the corner read
 * as a card PARKED in the frame rather than part of it. Squaring all four
 * was rejected too: the top-left is the frame's own corner (they curve
 * together, so there is no junction to break) and the bottom-right touches no
 * frame edge, and the drawing he approved rounds both.
 *
 * WHY a Block prop and not a rule inside `BlockRegion` (Zach, 2026-09-22:
 * "the block region styling we apply to the block like corning the corners.
 * that is just a styling change to Block"): a canvas host may mount the corner
 * card as an INDEPENDENT element. `apps/systemsketch` paints it as a real
 * `ss-block` child shape, so it is not a React descendant of the region and no
 * CSS rule the region writes can reach it. It is a fact about the card's own
 * outline, so it travels with the card. It used to be an exported style object
 * every host had to remember to spread (`REGION_CORNER_BLOCK_STYLE`), and a
 * `BlockRegion` story that forgot it shipped the all-round card (2026-09-22).
 * A named shape is harder to forget than an object to spread.
 */
export type BlockShape = "card" | "region-corner";

/** The card radius, the value every Block wore before `shape` existed. */
const CARD_RADIUS = "var(--bbox-skin-radius, var(--radius-lg))";

/**
 * The region frame's shared top-left radius. `BlockRegion`'s frame reads this
 * same chain, and a `region-corner` Block curves with it. `v1` resolves to the
 * skin radius. A region drawing (`skin/regionVariants.css`) sets
 * `--bbox-region-frame-radius` on an ancestor, and the frame and its corner
 * card both follow, because both read this one string.
 */
export const REGION_FRAME_RADIUS = "var(--bbox-region-frame-radius, var(--bbox-skin-radius, var(--radius-lg)))";

type CornerRadii = { tl: string; tr: string; br: string; bl: string };

const SHAPE_RADII: Record<BlockShape, CornerRadii> = {
  card: { tl: CARD_RADIUS, tr: CARD_RADIUS, br: CARD_RADIUS, bl: CARD_RADIUS },
  "region-corner": {
    tl: REGION_FRAME_RADIUS,
    tr: "0px",
    // The one free corner follows the drawing: `v2` and `v10` square it so
    // a full-width header rule leaves the card cleanly instead of from a curve.
    br: `var(--bbox-region-corner-radius, ${REGION_FRAME_RADIUS})`,
    bl: "0px",
  },
};

/** `border-radius` for a shape, optionally grown by `growPx` at every corner
 *  (the mask highlighter's Minkowski offset). A card's four equal corners stay
 *  the single value they always were, so a card's inline style is unchanged. */
function shapeRadiusCss(shape: BlockShape, growPx = 0): string {
  const r = SHAPE_RADII[shape];
  const grow = (value: string) => (growPx ? `calc(${value} + ${growPx}px)` : value);
  if (r.tl === r.tr && r.tr === r.br && r.br === r.bl) return grow(r.tl);
  return [r.tl, r.tr, r.br, r.bl].map(grow).join(" ");
}

export interface BlockProps {
  header?: ReactNode;
  body?: ReactNode;
  footer?: ReactNode;
  width?: number;
  /** Explicit height in px. Omit to hug the rendered regions. */
  height?: number;
  /** The outline: `"card"` (default) or `"region-corner"`. See `BlockShape`. */
  shape?: BlockShape;
  style?: CSSProperties;
  /**
   * The divider line under the header. Defaults to shown, so no existing
   * caller changes. WHY a prop and not a className override: SystemSketch's
   * own Block chrome treats "Header divider: Show|Hide" as a first-class
   * toggle beside "Footer: Show|Hide" (blockModel.ts's
   * `BlockShowHeaderDividerStyle`) — a header-only card (Zach's minimal
   * "Attributes" variant) wants the title to sit directly on the body with
   * no line between. Footer hiding needs no prop: omit `footer` and the
   * region is omitted entirely (the existing contract).
   */
  showHeaderDivider?: boolean;
  /**
   * The sentence under the title. Ported from the frozen v1 lineage —
   * `packages/bbox-ui/src/blockFace.tsx:437-454` paints it immediately after
   * the header in both header modes, which is the placement restated here.
   *
   * WHY it is a Block prop and not something a caller stuffs into `body`:
   * v1 governs it as a FIELD (`block.fields.ts`'s `DESCRIPTION_FIELD`) with
   * its own visibility toggle, so "is there a description, and is it shown"
   * is a question about the block, answerable without inspecting whatever
   * ReactNode a host happened to pass. The whiteboard's right-hand inspector
   * asks exactly that question.
   */
  description?: string;
  /**
   * Whether the description paints. Defaults to `true` — the donor field's
   * own `defaultValue: true` (`block.fields.ts:120-124`), so no existing
   * caller changes and a newly-typed description is visible immediately.
   *
   * WHY a separate boolean rather than clearing `description` to hide it
   * (Zach, ruling 9 — the control is an EYE, in the right-hand inspector):
   * an eye hides; it does not delete. Folding the two into one field would
   * mean toggling visibility off threw the author's text away, and toggling
   * it back on gave them an empty block.
   */
  showDescription?: boolean;
  /**
   * The description region, rendered BY THE HOST instead of by this component.
   * When present it replaces the whole region — the `<p>` included — and both
   * `description` and `showDescription` are then the host's business.
   *
   * WHY a host would need this at all: a host that lets a person edit the
   * description WHERE IT IS PAINTED has to swap the sentence for a control in
   * this exact spot, between the header and the body, and a `string` prop
   * cannot carry a control. `header` and `body` already work this way; this is
   * the same seam for the one region that did not have it. Zach's "edit it in
   * place, on the card, not in a panel field somewhere else" (P-039/P-026) is
   * what it is for, and `apps/systemsketch/src/shapes/block/BlockFace.tsx` is
   * the caller.
   *
   * WHY it is additive rather than widening `description` to a `ReactNode`,
   * which is the obvious move: `description` is a governed FIELD (see its own
   * doc above) and `blockDescriptionIsPainted` has to be able to ask whether
   * it is empty. A ReactNode cannot be asked that, so widening the prop would
   * either drop the gate or make it lie. Every existing caller is byte
   * -identical, because a caller that passes nothing here takes the branch it
   * always took.
   */
  descriptionSlot?: ReactNode;
  /**
   * Membership — "boxes all the way down". Members render in their own
   * region between body and footer; `membersLayout` picks how the ONE
   * member list is laid out (free = a frame inside, stack = an ordered
   * column). See ./blockMembers.tsx for the vocabulary and its
   * SystemSketch provenance.
   */
  members?: BlockMember[];
  membersLayout?: BlockMembersLayout;
  /** Enables drag-to-reorder of stacked members, kanban-card style. */
  onMembersChange?(members: BlockMember[]): void;
  memberGap?: number;
  memberGutter?: number;
  insetBackground?: BlockInsetBackground;
  showMembers?: boolean;
  showCards?: boolean;
  /**
   * The diagnostic axis (docs/INVALID-STATES-PLAN.md §5's Block row,
   * amended by Zach's report feedback — see `HighlighterKind`'s own doc
   * in ./highlighter.tsx). `error`/`warning` get a mark in whichever
   * `highlighterKind` the caller asked for, plus the corner
   * `DiagnosticFlag`; `info` paints nothing at all, matching §5's
   * board-scale calm rule. The flag carries a COUNT once the list is
   * longer than one (`DiagnosticFlag`'s own doc).
   *
   * The `"halo"` kind keeps its ORIGINAL, narrower rule — `error` alone,
   * "warning must not shout" — because a soft ambient glow is genuinely
   * loud; `"stroke"`/`"mask"` mark both severities uniformly (a crisp
   * outline does not have the same shouting problem), matching how
   * JointJS's own highlighters behave.
   */
  diagnostics?: Diagnostic[];
  /** Which `HighlighterKind` draws the mark. Defaults to
   *  `DEFAULT_HIGHLIGHTER_KIND` ("stroke") — Zach's own lean from the
   *  report feedback; `"halo"` is the pre-existing treatment, kept as a
   *  sibling, not deleted. */
  highlighterKind?: HighlighterKind;
  /**
   * Suppress the corner `DiagnosticFlag` while keeping the mark (default
   * `true` — every existing caller unchanged). `ValueCapsule`
   * (components/block.value.tsx) is the one caller that sets this `false`:
   * §5's own words are "no flag — a capsule is too small, the glow is the
   * beacon and the message rides a hover Tooltip" — the mark is still
   * this component's, the flag specifically is not.
   */
  showDiagnosticFlag?: boolean;
  /**
   * Let `warning` earn the `"halo"` kind's mark too (default `false` —
   * Block's own row: "warning must not shout"). Only meaningful with
   * `highlighterKind="halo"` — `"stroke"`/`"mask"` already mark both
   * severities regardless. `ValueCapsule` sets this `true` for its OWN
   * row ("warning: amber glow"), because a capsule has no flag at all to
   * carry warning instead. Block itself never sets this.
   */
  diagnosticWarningGlow?: boolean;
  /**
   * Stable string the sketch skin's hand-drawn outline is generated from —
   * same seed, same wobble, every render (see sketchPath.ts). Defaults to
   * a size-derived string so two same-sized Blocks don't draw identical
   * wobble by coincidence of both falling back the same way; pass an id
   * when two same-sized Blocks need visibly different hand-drawn lines.
   */
  sketchSeed?: string;
  /**
   * Paint Block's hit region. Block has NO hit constant — deliberately: as
   * a DOM element its pointer target is the browser's own hit test, which
   * stops at the border box exactly (the same "there was no number to
   * choose" React Flow's DOM nodes have; contrast tldraw's ±3 screen px
   * `hitTestMargin`). So what this paints IS that fact: a wash over the
   * border box, nothing outside it. Pure paint — absolutely positioned,
   * `pointer-events: none`, moves no layout and eats no clicks.
   */
  showHitRegion?: boolean;
}

/**
 * The root's own border width, px, used only to size `overflowClipMargin`
 * below. A literal, not `--bbox-skin-stroke-width` read back out of CSS:
 * this app carries no wall-anchor geometry that needs the two to be the
 * SAME variable (donor's block.tsx / skin.css both flag that trap — see
 * skin.css's own port-of-omission note), so a plain constant is honest
 * here. It still has to match the token's stroke-width fallback (2px) or
 * the clip margin would come up short the moment a skin activates.
 *
 * WHY this no longer feeds a drawn line: before
 * docs/peps/0001-sketch-skin-at-the-boundary.md, this fed `SketchOutline`
 * directly. The boundary pass now measures its own pen width off
 * `getComputedStyle(el).borderTopWidth` (`sketchAtEdge.ts`'s `measureBox`),
 * which is more honest than a duplicated literal — this constant only
 * has to stay right for the clip allowance, not for two things at once.
 */
const BLOCK_BORDER_PX = 2;

/**
 * WHY: docs/peps/0001-sketch-skin-at-the-boundary.md M2. Slack for any
 * decorative child that paints just outside the border box — NOT a skin
 * import, and not a number the skin gets to set. Before this migration
 * this was `SKETCH_OUTLINE_BLEED_PX`, imported from the skin because the
 * in-core `SketchOutline` was that decorative child; the boundary's own
 * twin is now appended as a child of THIS element (`sketchAtEdge.ts`'s
 * `upsertBoxTwin`) after this component has already rendered, so the same
 * clip allowance is still needed, just granted generically rather than
 * borrowed from the thing that used to need it. Value unchanged: 5, the
 * same `Math.ceil(SKETCH_WOBBLE_PX + 2)` the donor computed.
 */
const OUTLINE_BLEED_PX = 5;

export function Block({
  header,
  body,
  footer,
  width = 320,
  height,
  shape = "card",
  style,
  showHeaderDivider = true,
  description,
  showDescription = true,
  descriptionSlot,
  members,
  membersLayout = "free",
  onMembersChange,
  memberGap = BLOCK_MEMBER_GAP_PX,
  memberGutter = BLOCK_MEMBER_INSET_PX,
  insetBackground = "none",
  showMembers = true,
  showCards = false,
  diagnostics,
  highlighterKind = DEFAULT_HIGHLIGHTER_KIND,
  showDiagnosticFlag = true,
  diagnosticWarningGlow = false,
  sketchSeed,
  showHitRegion = false,
}: BlockProps) {
  const diagnosticSeverity = maxDiagnosticSeverity(diagnostics);
  const markedSeverity = diagnosticSeverity !== "info" ? diagnosticSeverity : undefined;
  // "Warning must not shout" (§5's own words for this row) is the
  // "halo" kind's OWN, narrower rule — an error-only escalation by
  // default, never amber, unless the caller (ValueCapsule) has no other
  // channel and opts warning in. `stroke`/`mask` mark both severities
  // uniformly — a crisp outline is not the loud thing "must not shout"
  // was written about.
  const showGlow =
    highlighterKind === "halo" &&
    (markedSeverity === "error" || (markedSeverity === "warning" && diagnosticWarningGlow));
  const showStroke = highlighterKind === "stroke" && markedSeverity != null;
  const showMask = highlighterKind === "mask" && markedSeverity != null;
  const showFlag = showDiagnosticFlag && markedSeverity != null;
  // Half the flag's own diameter pokes outside the border — "straddling
  // the corner the way wall ports straddle walls" (§5). `overflowClipMargin`
  // below has to widen to let it, exactly the mechanism already in place
  // for the sketch outline's own bleed (this file's existing WHY on
  // `overflow: clip`). The "mask" kind renders a SIBLING frame (below) that
  // pokes out by the same amount for the same reason; "stroke" needs no
  // widening at all — a CSS `outline` paints outside the border box but is
  // NOT part of what the element's own `overflow` clips (same rule that
  // already let the pre-existing glow's box-shadow skip this entirely).
  const flagOverhangPx = DIAGNOSTIC_FLAG_SIZE_PX / 2;
  const MASK_OFFSET_PX = 4;
  const maskOverhangPx = showMask ? MASK_OFFSET_PX : 0;
  return (
    <div
      data-slot="block"
      data-block-shape={shape}
      data-diagnostic={diagnosticSeverity}
      data-highlighter-kind={markedSeverity ? highlighterKind : undefined}
      className={cn(
        "relative flex flex-col text-sm",
        // Text colour is a skin token because a skin may remove the
        // surface it was contrasting against: the sketch skin paints no
        // fill, so `text-card-foreground` would be reading against a card
        // that is not there. Fallback is the exact class this replaced.
        "text-[color:var(--bbox-skin-fg,var(--color-card-foreground))]",
        // The skin seam (src/skin/skin.ts + skin.css). Each token carries
        // TODAY'S value as its own `var()` fallback — captured live off
        // this story before this port (`components-blocks-block--default`,
        // getComputedStyle) — so a consumer who never imports skin.css
        // renders the exact pixels this replaced: `rounded-lg border
        // border-border bg-card shadow-sm`. `border-solid` is explicit
        // because a host without Tailwind's preflight defaults to
        // `border-style: none`, where a width alone paints nothing.
        // WHY the fallback is 1px, not the token table's 2px: Block's own
        // border-width TODAY is Tailwind's plain `border` utility (1px) —
        // captured live (`components-blocks-block--default`, getComputedStyle) before
        // this port. skin.css's three blocks still all agree on 2px once
        // ANY skin is active (including the explicit "default" one) — see
        // skin.css's own header on why stroke-width has to be uniform
        // across every skinned component the moment a skin is switched
        // on. Only the UNSET case (no attribute at all) has to stay 1px.
        "border-solid border-[length:var(--bbox-skin-stroke-width,1px)] border-[color:var(--bbox-skin-stroke,var(--color-border))]",
        "bg-[var(--bbox-skin-surface,var(--color-card))] shadow-[var(--bbox-skin-shadow,0_1px_3px_0_rgb(0_0_0_/_0.1),0_1px_2px_-1px_rgb(0_0_0_/_0.1))]",
        // Set once on the container; every text slot inherits it, so the
        // sketch skin needs no per-slot font prop.
        "font-[family-name:var(--bbox-skin-font,inherit)]",
      )}
      // `overflow: clip` (not `hidden`) so the header/footer bars' corners
      // still cut cleanly without turning Block into a scroll container —
      // and so a decorative child painting just outside the padding box
      // (a boundary-drawn twin; see `OUTLINE_BLEED_PX`) isn't clipped;
      // see `overflowClipMargin` below.
      style={{
        // The isolation invariant (paintOrder.ts's own header comment):
        // this root emits paint tiers (the diagnostic flag below, and
        // headerChrome on the header/footer slots), so it MUST wall them
        // off in their own stacking context — otherwise a deeply nested
        // Block (via `BlockMembers`, "boxes all the way down") could leak
        // an interior z-index past this box and outrank an ANCESTOR's
        // own header. See PaintOrder.stories.tsx's
        // `NestedChildStaysBehindHeader`.
        ...ISOLATED_ROOT_STYLE,
        width,
        height,
        borderRadius: shapeRadiusCss(shape),
        // WHY here and not in a region stylesheet: `v10` centres the corner
        // card's title in a band run the full width of the region, and every
        // other drawing leaves it where the host put it. `text-align` is
        // INHERITED, so setting it on the card root reaches the title without
        // a descendant selector, and a descendant selector written in the
        // region could never reach the app's child-shape card anyway.
        // It cannot leak onto port labels: `BlockPort` is the card's PARENT.
        ...(shape === "region-corner"
          ? { textAlign: "var(--bbox-region-corner-title-align, initial)" as CSSProperties["textAlign"] }
          : null),
        overflow: "clip",
        // Widened to let the corner flag straddle the border (see
        // `flagOverhangPx` above) and, with `highlighterKind="mask"`, the
        // sibling mask frame (below) poke out too — the same clip-margin
        // mechanism this rule already grants a decorative child's own
        // bleed; every reason to widen it is independent, so this takes
        // whichever is largest rather than stacking them. `"stroke"` needs
        // no widening — see this file's own WHY on `showStroke` above.
        overflowClipMargin: `${BLOCK_BORDER_PX + Math.max(OUTLINE_BLEED_PX, showFlag ? flagOverhangPx : 0, maskOverhangPx)}px`,
        // PREPENDED ahead of the resting `shadow-[…]` utility (§3: "outer
        // halo... prepended") — an inline `boxShadow` beats a class at
        // equal specificity by cascade ORDER regardless, so this only sets
        // one when there is something to prepend; `undefined` otherwise
        // leaves the Tailwind utility above untouched, byte-identical to
        // before this axis existed. The wash is a soft, blurred colour-mix
        // of the SAME token as the ring, never a hardcoded red/amber — dark
        // mode gets the dark token variant for free.
        ...(showGlow && markedSeverity
          ? {
              boxShadow: `0 0 0 1.5px ${diagnosticColorVar(markedSeverity)}, 0 0 18px color-mix(in srgb, ${diagnosticColorVar(markedSeverity)} 45%, transparent), var(--bbox-skin-shadow, 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1))`,
            }
          : null),
        // `"stroke"` (HighlighterKind's own doc): a plain CSS outline, the
        // cheap JointJS-style approximation — same corner radius as the
        // box itself, not truly equidistant on a rounded rect.
        ...(showStroke && markedSeverity ? highlighterStrokeOutlineStyle(diagnosticColorVar(markedSeverity), 4) : null),
        ...style,
      }}
    >
      {showMask && markedSeverity && (
        // `"mask"` (HighlighterKind's own doc): a sibling frame whose
        // `border-radius` grows by EXACTLY the offset — the Minkowski-sum
        // arithmetic that makes this genuinely equidistant at the corners,
        // unlike `"stroke"`'s plain `outline-offset` above.
        <div
          data-slot="block-highlighter-mask"
          aria-hidden
          style={{
            ...highlighterMaskFrameStyle(diagnosticColorVar(markedSeverity), MASK_OFFSET_PX, CARD_RADIUS),
            // Per corner, so a region-corner card's square junctions grow to
            // square-plus-offset instead of a rounded frame around a square card.
            borderRadius: shapeRadiusCss(shape, MASK_OFFSET_PX),
          }}
        />
      )}
      {showFlag && diagnostics && (
        // Straddles the top-right corner — half in, half out — the same
        // convergence Appendix B's own table names (maxGraph's
        // `defaultOverlap: 0.5`, JointJS's `Button` at `x:'100%'`, Vyuh's
        // "-8px offset"). `zIndex` clears the sketch outline's own drawn
        // stroke, which otherwise paints OVER a flag sitting this close to
        // the corner.
        <div
          data-slot="block-diagnostic-flag"
          style={{ position: "absolute", top: -flagOverhangPx, right: -flagOverhangPx, zIndex: paintTier("flagBadge") }}
        >
          <DiagnosticFlag diagnostics={diagnostics} />
        </div>
      )}
      {showHitRegion && (
        <div
          data-slot="block-hit-region"
          aria-hidden
          style={{
            position: "absolute",
            // `inset: 0` covers the PADDING box; the hit region is the
            // BORDER box, so reach back out by the live border width —
            // the same token the root's own border reads.
            inset: "calc(-1 * var(--bbox-skin-stroke-width, 1px))",
            pointerEvents: "none",
            background: HIT_REGION_FILL,
            outline: HIT_REGION_OUTLINE,
            outlineOffset: -1,
            borderRadius: shapeRadiusCss(shape),
          }}
        />
      )}
      {header !== undefined && (
        <div
          data-slot="block-header"
          className={cn(
            "px-3 py-2 has-[>[data-slot=bar]]:p-0",
            // `border-b-[color:…]`, NOT the bare `border-[color:…]` this
            // was first written as: a bracketed arbitrary value with no
            // side prefix sets the property on all FOUR sides, which
            // silently added a 1px left/right/top border the div never
            // had — measured live (BlockPort.stories.tsx's
            // `FunctionPortHeaderInset`, off by 2px) before this fix.
            // `border-b` alone still supplies the bottom width + solid
            // style; this only overrides ITS colour.
            showHeaderDivider && "border-b border-b-[color:var(--bbox-skin-stroke,var(--color-border))]",
          )}
          // `headerChrome` (paintOrder.ts) — the nesting tier: a Block's
          // own header must paint ABOVE its own `BlockMembers` region no
          // matter how deeply that region nests other Blocks inside it
          // (Card 04). Needs BOTH `position` (z-index is a no-op on a
          // static element) and the explicit tier (a `BlockMembers`
          // region in `free` mode is itself `position: relative` with
          // z-index:auto, i.e. stack level 0 — a merely-positioned
          // header with no z-index would still lose the DOM-order
          // tie-break, since members renders AFTER header). This was
          // NOT one of the five pre-existing literals; it is the one
          // new capability this lane adds. See
          // `PaintOrder.stories.tsx`'s `NestedChildStaysBehindHeader`.
          style={{ position: "relative", zIndex: paintTier("headerChrome") }}
        >
          {header}
        </div>
      )}
      {/* The donor's placement, verbatim in intent: directly after the
          header, before the body, in every view. `blockDescriptionIsPainted`
          is v1's own `resolved.description && data.description` gate — an
          empty string paints nothing even with the eye on, so an untouched
          block never reserves a blank line. */}
      {descriptionSlot !== undefined
        ? descriptionSlot
        : blockDescriptionIsPainted(description, showDescription) && (
            <BlockDescription>{description}</BlockDescription>
          )}
      {body !== undefined && (
        <div
          data-slot="block-body"
          className="flex min-h-0 flex-1 items-center justify-center overflow-auto p-2"
        >
          {body}
        </div>
      )}
      {members !== undefined && (
        <BlockMembers
          layout={membersLayout}
          members={members}
          onMembersChange={onMembersChange}
          gap={memberGap}
          gutter={memberGutter}
          insetBackground={insetBackground}
          showMembers={showMembers}
          showCards={showCards}
        />
      )}
      {footer !== undefined && (
        <div
          data-slot="block-footer"
          className="border-t border-t-[color:var(--bbox-skin-stroke,var(--color-border))] px-3 py-2 has-[>[data-slot=bar]]:p-0"
          // Same tier as the header — see the header's own comment above.
          // Not covered by the nesting acceptance test (only the header
          // relationship is), but a footer is the same "chrome" role and
          // leaving it non-positioned would make it lose to members the
          // header no longer does.
          style={{ position: "relative", zIndex: paintTier("headerChrome") }}
        >
          {footer}
        </div>
      )}
    </div>
  );
}

// src/components/blockDescription.tsx — the sentence under a block's title,
// and the one boolean that decides whether it is painted at all.
//
// PORTED, not designed: packages/bbox-ui is the frozen v1 lineage and it
// already settled this feature's shape twice over —
//
//   - `src/block.fields.ts:120-124` — `{ id: "description", label:
//     "Description", kind: "toggle", defaultValue: true }`. Visibility is a
//     GOVERNED FIELD with a default of ON, not a prop someone remembers to
//     pass, which is why `showDescription` below defaults to `true`.
//   - `src/block.tsx:367-380` — `BlockDescription`: a `<p>` stamped
//     `data-slot="block-description"`, `text-muted-foreground`, an explicit
//     `fontSize`, caller `style` merged last.
//   - `src/blockFace.tsx:437-454` — WHERE it paints and WHEN: immediately
//     after the header, in BOTH header modes, and only when the resolved
//     boolean AND a non-empty string are both present
//     (`resolved.description && data.description`).
//
// This file restates those three facts for the trunk. `packages/bbox-ui` is
// not edited to match (ARCHITECTURE.md: "Never edit `packages/bbox-ui` to
// chase a trunk change").
import type { ComponentProps } from "react";

import { cn } from "../lib/utils";

/**
 * The description's own type size, px.
 *
 * WHY this is 12 and the donor's `META_FONT_PX` is 18: the donor's number is
 * calibrated to its Simple View box, which `layout.ts` fixes at 384 × 258.
 * The trunk's `Block` defaults to 320 wide and the whiteboard's own `ss-block`
 * defaults to 160 (`BlockShapeUtil.getDefaultProps`), where an 18px sentence
 * is wider than the card it is describing. 12 is the trunk's own meta step —
 * one below `Block`'s root `text-sm` (14) — so the description reads as
 * subordinate to the title at every size the trunk actually ships.
 *
 * Exported because a spatial claim about this element has to be measured
 * against the component's own constant rather than a number retyped in a
 * test (`BlockDescription.stories.tsx` asserts exactly that).
 */
export const BLOCK_DESCRIPTION_FONT_PX = 12;

/**
 * The description's inset, px — horizontally the SAME 12 as `Block`'s own
 * header/footer `px-3`, so the sentence's left edge lines up with the title
 * above it instead of sitting in its own gutter. Vertically tighter (`py-1`)
 * because it is a continuation of the header, not a third region.
 */
export const BLOCK_DESCRIPTION_PADDING_X_PX = 12;
export const BLOCK_DESCRIPTION_PADDING_Y_PX = 4;

/**
 * The donor's gate (`blockFace.tsx:437`), as one named predicate instead of
 * two `&&`s repeated at every paint site.
 *
 * WHY an empty string paints NOTHING even when the toggle is on: the donor's
 * face reads `resolved.description && data.description`, i.e. a block that has
 * never been given a description looks identical to one whose description is
 * hidden. Without this, the eye toggle's "on" state would reserve an empty
 * line under every untouched block on the board.
 *
 * Pure, and used by exactly one component — so by this repo's placement rule
 * it lives WITH that component rather than in `scene/`.
 */
export function blockDescriptionIsPainted(description: string | undefined, showDescription: boolean): boolean {
  return showDescription && typeof description === "string" && description.trim() !== "";
}

/**
 * The text slot itself. `ComponentProps<"p">` and a merged `style`, exactly
 * the donor's own signature — a caller may restyle it; it may not make
 * authored characters disappear (`feedback_truthful_property_rendering`),
 * which is why nothing here truncates or clips.
 */
export function BlockDescription({ className, style, ...props }: ComponentProps<"p">) {
  return (
    <p
      data-slot="block-description"
      className={cn("text-muted-foreground", className)}
      style={{
        fontSize: BLOCK_DESCRIPTION_FONT_PX,
        lineHeight: 1.35,
        padding: `${BLOCK_DESCRIPTION_PADDING_Y_PX}px ${BLOCK_DESCRIPTION_PADDING_X_PX}px`,
        // The board stores one string; a newline the author typed is a
        // newline they meant. `pre-wrap` also keeps runs of spaces, which is
        // the same "render stored properties truthfully" rule the port
        // declaration already follows.
        whiteSpace: "pre-wrap",
        ...style,
      }}
      {...props}
    />
  );
}

"use client";

// src/components/blockMembers.tsx — Block membership: the members region a
// Block renders between its body and footer. Free vs Stack are two layout
// modes over the SAME member list ("free vs stack is basically the same
// thing, it's all just membership" — Zach), never two features: `free`
// places each member at its own authored (x, y) like a frame's canvas;
// `stack` lays the same list out as an ordered column, drag-reorderable
// like kanban cards.
//
// Ported by value from SystemSketch (read-only donor, never imported):
//   - `BLOCK_MEMBER_INSET_PX` / `BLOCK_MEMBER_GAP_PX` = 12
//     (src/blocks/memberLayout.ts:18) — the gutter/gap defaults.
//   - the layout vocabulary (src/blocks/blockModel.ts): body layouts
//     `free | stack`, member widths `fill | own`, member spacing
//     `inset | edge-to-edge`, inset backgrounds none vs soft gray.
//   - the geometry of `stackMemberPlacements` (memberLayout.ts:60): first
//     slot one gap below the header, members follow in list order, a fill
//     member takes `inner - gutter*2` — restated here as flex column
//     geometry (rowGap + per-slot margins) instead of computed x/y
//     writes, because this app is props-in DOM-out, not a tldraw store.
//   - `blockMemberDropTarget`'s midpoint rule (memberLayout.ts:84) is
//     subsumed by dnd-kit's own `closestCenter` — not re-ported.
//
// WHY spacing and width are PER MEMBER here where the donor kept them
// parent-level: the donor's own `BLOCK_MEMBER_WIDTHS` comment says
// "Parent-level on purpose for V1; a per-member override is the documented
// follow-up" — Zach is now asking for exactly that follow-up ("we want to
// be able to apply these settings on a per member setting"), so the
// per-member move is the deliberate delta from the donor, not a drift.
//
// The dnd machinery mirrors portEdge.tsx (this app's prior art for
// kanban-style reorder): PointerSensor with a 4px activation distance, and
// `neutralizeScale` pinning scaleX/scaleY to 1 — see that file's B1
// comment for why `useDerivedTransform` otherwise stretches non-uniform
// siblings mid-reorder. The whole DndContext only mounts when the caller
// passes `onMembersChange` AND the layout is `stack`: a static gallery
// (or a nested Block inside a sortable member) never grows drag listeners
// it can't honour, which is also what keeps nested membership safe from
// two DndContexts fighting over one pointerdown.
import {
  DndContext,
  PointerSensor,
  closestCenter,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import { SortableContext, arrayMove, useSortable, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import type { CSSProperties, ReactNode } from "react";

import { cn } from "../lib/utils";

/* ------------------------------------------------------------------ */
/* Vocabulary — the donor's enums, restated as string unions.           */
/* ------------------------------------------------------------------ */

export type BlockMembersLayout = "free" | "stack";
/** Per member: inset (a card with breathing room) vs edge-to-edge (full inner width). */
export type BlockMemberInset = "inset" | "edge-to-edge";
/** Per member: take the parent's inner width (Fill) or keep its own (Own). */
export type BlockMemberWidth = "fill" | "own";
/** Block-level surface behind the members — "basically just differentiates it a bit". */
export type BlockInsetBackground = "none" | "soft-gray";

export const BLOCK_MEMBER_INSET_PX = 12;
export const BLOCK_MEMBER_GAP_PX = 12;

export interface BlockMember {
  id: string;
  /** Arbitrary content: another Block, a CodeEditor, text — boxes all the way down. */
  content: ReactNode;
  /** Free-mode position, px, relative to the members region. Ignored by
   *  `stack` — which is what makes a free→stack→free round trip lossless:
   *  stacking never rewrites these. */
  x?: number;
  y?: number;
  /** Per-member spacing. Defaults to `"inset"`. */
  inset?: BlockMemberInset;
  /** Per-member width. Defaults to `"fill"`. */
  width?: BlockMemberWidth;
  /**
   * WHY: rectangles/arrows can be members but make no sense stacked —
   * Zach's ruling is "they should keep their membership but have their
   * visibility turned off". `false` keeps the member in the list (and in
   * any future members panel) while rendering nothing.
   */
  visible?: boolean;
}

export interface BlockMembersProps {
  layout: BlockMembersLayout;
  members: BlockMember[];
  /** Enables drag-to-reorder in `stack` layout. Omit for a static region. */
  onMembersChange?(members: BlockMember[]): void;
  /** Vertical gap between stacked members, and the stack's top/bottom padding. */
  gap: number;
  /** Horizontal inset an `"inset"` member sits in from the Block's inner edge. */
  gutter: number;
  insetBackground: BlockInsetBackground;
  /** Off = member content leaves the DOM entirely (not opacity 0). */
  showMembers: boolean;
  /**
   * WHY overlay, not container (2026-09-17,
   * docs/FEEDBACK-2026-09-17b-PLAN.md, Lane B — "I don't like how when you
   * show the cards it kinda changes the shape of how the members look"):
   * the card is a VIEW of membership that's always true — those cards are
   * always "there" in spirit — so drawing it must never move the thing it
   * describes. On = a translucent red, Chrome-inspector-style outline is
   * painted OVER each member's existing box; it never wraps, pads or
   * insets the content, which is exactly what the old "sits inside a
   * kanban-style card surface" wrapper did wrong.
   */
  showCards: boolean;
}

/* ------------------------------------------------------------------ */
/* Slot geometry                                                       */
/* ------------------------------------------------------------------ */

// A card whose member content is hidden still reads as a card — same as
// portEdge.tsx's empty-card behaviour ("showCard alone still reads as a
// real (if empty) card"), so "hide the members and just focus on the card
// interactions" has cards left to interact with. This is the ONE place the
// overlay is still allowed to affect geometry: with no content there is no
// content box left to preserve, so the SLOT reserves the footprint instead
// (the overlay itself never sizes anything — see `memberSlotChildren`).
export const EMPTY_CARD_MIN_PX = 24;
// Chrome DevTools' own element-highlight recipe: translucent fill + a solid
// edge, red because that's what Zach asked for. Same split as portEdge.tsx's
// identical overlay: the skin seam touches SHAPE only (radius, stroke-width)
// — this red stays exactly this red in every skin, a deliberate ruling, not
// a state the skin owns.
const CARD_OVERLAY_FILL = "rgb(239 68 68 / 0.18)";
const CARD_OVERLAY_BORDER = "rgb(239 68 68 / 0.7)";
const CARD_OVERLAY_RADIUS = "var(--bbox-skin-radius, var(--radius-lg))";
const CARD_OVERLAY_STROKE_WIDTH = "var(--bbox-skin-stroke-width, 1px)";

interface MemberSlotProps {
  member: BlockMember;
  layout: BlockMembersLayout;
  gutter: number;
  showMembers: boolean;
  showCards: boolean;
}

function resolveMemberContent({ member, showMembers }: MemberSlotProps): ReactNode {
  return showMembers ? member.content : null;
}

function slotStyle(props: MemberSlotProps): CSSProperties {
  const { member, layout, gutter, showCards } = props;
  // The one geometry-affecting case: no content box exists to keep
  // identical, so the slot (not the overlay) reserves the footprint.
  const reserveEmptyFootprint = showCards && resolveMemberContent(props) == null;
  if (layout === "free") {
    // The frame inside: authored position, own size — like the canvas
    // outside. `position: absolute` already establishes the containing
    // block the overlay positions against, same as `relative` would.
    return {
      position: "absolute",
      left: member.x ?? 0,
      top: member.y ?? 0,
      width: "max-content",
      ...(reserveEmptyFootprint ? { minHeight: EMPTY_CARD_MIN_PX } : null),
    };
  }
  const inset = (member.inset ?? "inset") === "inset";
  const own = (member.width ?? "fill") === "own";
  return {
    // `position: relative` so the overlay (`absolute inset-0`, added in
    // `memberSlotChildren`) positions against the slot itself.
    position: "relative",
    // WHY block layout, not flex: a block-level child (a Block, a
    // CodeEditor, a plain div) then fills the slot's width naturally,
    // which is what `fill` means; a flex slot would shrink children to
    // max-content and quietly break it.
    marginLeft: inset ? gutter : 0,
    marginRight: inset ? gutter : 0,
    // Own: the slot hugs its content and left-aligns where the donor
    // placed it (x = gutter for inset, 0 for edge-to-edge).
    ...(own ? { alignSelf: "flex-start", width: "max-content" } : null),
    ...(reserveEmptyFootprint ? { minHeight: EMPTY_CARD_MIN_PX } : null),
  };
}

/**
 * Content plus, when `showCards`, a sibling overlay — NEVER a wrapper.
 * `position: absolute inset-0` makes the overlay contribute nothing to the
 * slot's own size, and `pointer-events: none` keeps it out of the way of
 * drag/reorder (B3) — an overlay the pointer could hit would steal the
 * gesture that reorders members.
 */
function memberSlotChildren(props: MemberSlotProps): ReactNode {
  const content = resolveMemberContent(props);
  if (!props.showCards) return content;
  return (
    <>
      {content}
      <div
        aria-hidden
        data-slot="block-member-card"
        className="pointer-events-none absolute inset-0 border"
        style={{
          borderRadius: CARD_OVERLAY_RADIUS,
          borderWidth: CARD_OVERLAY_STROKE_WIDTH,
          backgroundColor: CARD_OVERLAY_FILL,
          borderColor: CARD_OVERLAY_BORDER,
        }}
      />
    </>
  );
}

function memberSlotData(member: BlockMember) {
  return {
    "data-slot": "block-member",
    "data-member-id": member.id,
    "data-member-inset": member.inset ?? "inset",
    "data-member-width": member.width ?? "fill",
  } as const;
}

/**
 * WHY an edge-to-edge member squares ALL FOUR corners of its outermost box
 * (`[&>*]` — the card surface or the bare content, never anything deeper):
 * Zach's ruling — "when block goes edge to edge, its corners should not be
 * radius, so it looks like it's part of the parent block". A rounded corner
 * on a flush member reads as a separate card that happens to touch; square
 * corners merge it into the parent's surface. All four rather than only the
 * flush left/right sides: a stacked member only ever touches the parent's
 * left/right inner edges (the header and the region's own gap padding keep
 * it off the top and bottom), and in the degenerate case where one does
 * reach a real corner, the parent Block's own `overflow-hidden rounded-lg`
 * re-clips it to the parent's radius anyway — so following the parent's
 * radius from the inside would only duplicate what the clip already
 * guarantees. An inset member keeps its radius on purpose: it IS a
 * separate card. Free-mode members are never flush, so nothing applies.
 */
function slotClassName(member: BlockMember, layout: BlockMembersLayout): string | undefined {
  if (layout !== "stack") return undefined;
  return (member.inset ?? "inset") === "edge-to-edge" ? "[&>*]:rounded-none!" : undefined;
}

function StaticMemberSlot(props: MemberSlotProps) {
  return (
    <div
      {...memberSlotData(props.member)}
      className={slotClassName(props.member, props.layout)}
      style={slotStyle(props)}
    >
      {memberSlotChildren(props)}
    </div>
  );
}

/**
 * portEdge.tsx's B1 fix, copied by value: `useSortable`'s transform can
 * carry a scaleX/scaleY "squeeze" from `useDerivedTransform` on any
 * sibling whose rect differs from the dragged one's — members are
 * arbitrary content, so theirs always differ. Pin scale to 1; only ever
 * translate.
 */
function neutralizeScale(transform: Parameters<typeof CSS.Transform.toString>[0]) {
  if (!transform) return transform;
  return { ...transform, scaleX: 1, scaleY: 1 };
}

function SortableMemberSlot(props: MemberSlotProps) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: props.member.id });
  const style: CSSProperties = {
    ...slotStyle(props),
    transform: CSS.Transform.toString(neutralizeScale(transform)),
    transition,
    opacity: isDragging ? 0.35 : 1,
    cursor: "grab",
    touchAction: "none",
  };
  return (
    <div
      ref={setNodeRef}
      {...memberSlotData(props.member)}
      className={slotClassName(props.member, props.layout)}
      data-dragging={isDragging || undefined}
      style={style}
      {...attributes}
      {...listeners}
    >
      {memberSlotChildren(props)}
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* The region                                                          */
/* ------------------------------------------------------------------ */

export function BlockMembers({ layout, members, onMembersChange, gap, gutter, insetBackground, showMembers, showCards }: BlockMembersProps) {
  // Both toggles off: nothing member-related renders at all — the Block
  // itself still stands (its header/body/footer are not this region's).
  if (!showMembers && !showCards) return null;

  const rendered = members.filter((member) => member.visible !== false);
  const sortable = layout === "stack" && onMembersChange !== undefined;

  const regionStyle: CSSProperties =
    layout === "free"
      ? // The frame inside: fills whatever height the Block gives it. A free
        // region needs the Block to carry an explicit height — absolutely
        // positioned members contribute none, same as a canvas.
        { position: "relative", flex: 1, minHeight: 0, alignSelf: "stretch" }
      : // The donor's stack geometry: first member one gap below the header,
        // one uniform gap between members, one gap before whatever follows.
        { display: "flex", flexDirection: "column", rowGap: gap, paddingTop: gap, paddingBottom: gap };

  const region = (
    <div
      data-slot="block-members"
      data-layout={layout}
      data-inset-background={insetBackground}
      className={cn(insetBackground === "soft-gray" && "bg-muted/50")}
      style={regionStyle}
    >
      {rendered.map((member) => {
        const slotProps: MemberSlotProps = { member, layout, gutter, showMembers, showCards };
        return sortable ? <SortableMemberSlot key={member.id} {...slotProps} /> : <StaticMemberSlot key={member.id} {...slotProps} />;
      })}
    </div>
  );

  if (!sortable) return region;
  return (
    <MemberDndBoundary members={members} renderedIds={rendered.map((member) => member.id)} onMembersChange={onMembersChange}>
      {region}
    </MemberDndBoundary>
  );
}

function MemberDndBoundary({
  members,
  renderedIds,
  onMembersChange,
  children,
}: {
  members: BlockMember[];
  renderedIds: string[];
  onMembersChange(members: BlockMember[]): void;
  children: ReactNode;
}) {
  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 4 } }));
  function handleDragEnd({ active, over }: DragEndEvent) {
    if (!over || over.id === active.id) return;
    // Indexes resolved against the FULL member list, so a hidden member
    // (visible: false) keeps its membership through a reorder of its
    // visible siblings.
    const from = members.findIndex((member) => member.id === active.id);
    const to = members.findIndex((member) => member.id === over.id);
    if (from === -1 || to === -1) return;
    onMembersChange(arrayMove(members, from, to));
  }
  return (
    <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
      <SortableContext items={renderedIds} strategy={verticalListSortingStrategy}>
        {children}
      </SortableContext>
    </DndContext>
  );
}

// src/components/blockRegion.layout.ts — BlockRegion's vertical geometry as a PURE
// function: where the corner block sits, where the free body starts, and
// how arms stack. CONTRACT STUB — docs/CONTROL-FLOW-PLAN.md, lane A.
// Signatures and constants frozen by `blockRegion.layout.test.ts`.
//
// PROVENANCE: the stacking rule is SystemSketch's `branchLayout`
// (`/home/bam/systemsketch/src/branch/branchModel.ts:161-230`, read
// 2026-09-18): rows are a running cursor, `bodyTop = rowTop + header`,
// `bodyH = open ? h : 0`, `bottom = bodyTop + bodyH`, next row's top is
// this row's bottom, and the region's height is the cursor plus a bottom
// pad. Ported by VALUE (restated in this repo's names), not by import. The
// one deliberate change: the first row starts under the CORNER BLOCK, not
// under a full-width band — Zach's 2026-09-18 ruling replaced the band with
// a real Block in the frame's top-left corner ("OLD: BAD / NEW: GOOD",
// `Pasted image 20260918150916.png`).
//
// WHY a pure twin exists when the DOM could stack arms with flexbox: the
// component positions arm rows from THIS function (with a measured corner
// height), so a host that needs arm geometry WITHOUT rendering — a drop
// target, an SVG export, stream 2's tldraw shape — reads the same numbers
// the paint used. SystemSketch's own reason (branchModel.ts:14-16): "a
// fold, an added arm and a tldraw resize all agree about where every row
// is."
//
// Pure: no React, no DOM.

/** Donor `BRANCH_ARM_HEADER_HEIGHT` (branchModel.ts:29). */
export const REGION_ARM_HEADER_PX = 32;
/** Donor `BRANCH_DEFAULT_ARM_HEIGHT` (branchModel.ts:31). */
export const REGION_ARM_DEFAULT_BODY_PX = 180;
/** Donor `BRANCH_MIN_ARM_HEIGHT` (branchModel.ts:32). */
export const REGION_ARM_MIN_BODY_PX = 48;
/** Ours: an empty loop/group still shows a body to drop into. */
export const REGION_BODY_MIN_PX = 120;
/** `BLOCK_MEMBER_INSET_PX` (blockMembers.tsx) — the same 12 the members
 *  region already breathes by; the donor's own pad was 10. */
export const REGION_PAD_BOTTOM_PX = 12;
/** Donor `BRANCH_MIN_WIDTH` (branchModel.ts:33). */
export const REGION_MIN_WIDTH_PX = 240;
/** Donor `BRANCH_FADE_OPACITY` (branchModel.ts:38-39): "Non-active arms,
 *  their Blocks and their cables fade to this. One token." */
export const REGION_ARM_FADE_OPACITY = 0.18;
/** The corner block's width in the expanded view — Zach's "NEW GOOD"
 *  sketch draws a compact port-view block (~140px) in the frame's corner,
 *  not a full 320px Block. Height hugs the ports. */
export const REGION_CORNER_WIDTH_PX = 160;
/** The opaque card's width (P5): wider than the corner because it also
 *  carries the promoted boundary ports and a footer. Height hugs. */
export const REGION_CARD_WIDTH_PX = 220;

export interface RegionRect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface RegionArmInput {
  id: string;
  open: boolean;
  /** Body height while open; remembered while folded. Default
   *  `REGION_ARM_DEFAULT_BODY_PX`; never below `REGION_ARM_MIN_BODY_PX`. */
  bodyHeight?: number;
}

export interface RegionLayoutInput {
  width: number;
  /** Explicit outer height. Omitted = hug: the last row's bottom plus
   *  `REGION_PAD_BOTTOM_PX` (or `corner.h + REGION_BODY_MIN_PX` with no arms).
   *  Given but too small for the arms = the arms win (the donor's
   *  `reconcileBranchProps` rule: `h` is kept in step with the arms). */
  height?: number;
  /** The corner block's measured (or declared) size. */
  corner: { w: number; h: number };
  arms?: readonly RegionArmInput[];
  /**
   * The arm header row's height. Default `REGION_ARM_HEADER_PX` (the
   * donor's 32). A region VARIANT may draw a shorter or taller header
   * (`skin/regionVariants.ts`, `arms.headerPx`) — and because this twin is
   * read by hosts that never render (a tldraw shape's geometry), the number
   * has to arrive as an input rather than be read off a computed style. A
   * host that switches variants passes
   * `REGION_VARIANTS[readRegionVariant()].arms.headerPx` here, or its rows
   * and the component's rows disagree by the difference.
   */
  armHeaderPx?: number;
}

export interface RegionArmLayout {
  id: string;
  index: number;
  open: boolean;
  /** The row = header + body. `rowTop` of arm 0 is `corner.h`. */
  rowTop: number;
  headerTop: number;
  bodyTop: number;
  /** 0 while folded. */
  bodyHeight: number;
  bottom: number;
}

export interface RegionLayout {
  width: number;
  height: number;
  /** Always `{x: 0, y: 0, w, h}` — the corner block IS the origin. */
  corner: RegionRect;
  /** The free body under the corner block. With arms present it has zero
   *  height (a branch has no free body; its arms are its body). */
  body: RegionRect;
  arms: RegionArmLayout[];
}

export function regionLayout(input: RegionLayoutInput): RegionLayout {
  const width = Math.max(input.width, REGION_MIN_WIDTH_PX);
  const corner = { x: 0, y: 0, w: input.corner.w, h: input.corner.h };

  // The donor's running cursor (branchModel.ts:161-230), restated: one row
  // is header + body, the body costs nothing while folded, and the next
  // row starts exactly where this one ended. The ONE change from the donor
  // is where the cursor starts — under the CORNER BLOCK, not under a
  // full-width band (Zach's 2026-09-18 "OLD: BAD / NEW: GOOD" ruling).
  const headerPx = input.armHeaderPx ?? REGION_ARM_HEADER_PX;
  let cursor = corner.h;
  const arms: RegionArmLayout[] = (input.arms ?? []).map((arm, index) => {
    const rowTop = cursor;
    const bodyTop = rowTop + headerPx;
    // WHY the clamp only applies while OPEN: `bodyHeight` is the height an
    // arm remembers, and a folded arm must remember the number it will
    // re-open at — clamping a folded arm to the minimum would silently
    // rewrite an authored 10 into 48 the moment someone folded it.
    const bodyHeight = arm.open ? Math.max(arm.bodyHeight ?? REGION_ARM_DEFAULT_BODY_PX, REGION_ARM_MIN_BODY_PX) : 0;
    const bottom = bodyTop + bodyHeight;
    cursor = bottom;
    return { id: arm.id, index, open: arm.open, rowTop, headerTop: rowTop, bodyTop, bodyHeight, bottom };
  });

  // Hug: the last row's bottom plus the pad, or — with no arms — enough
  // room for the free body a loop/group drops into. An explicit `height`
  // may only ever make the region TALLER; the donor's own
  // `reconcileBranchProps` keeps `h` in step with the arms for the same
  // reason, and a frame shorter than its own rows would paint arms outside
  // the border they are supposed to live in.
  const hugged = arms.length > 0 ? cursor + REGION_PAD_BOTTOM_PX : corner.h + REGION_BODY_MIN_PX;
  const height = Math.max(input.height ?? 0, hugged);

  return {
    width,
    height,
    corner,
    // A branch has no free body: its arms ARE its body (plan §3.2). Kept as
    // a zero-height rect at the same origin rather than omitted, so a
    // caller reads one shape either way.
    body: { x: 0, y: corner.h, w: width, h: arms.length > 0 ? 0 : height - corner.h },
    arms,
  };
}

"use client";

// src/components/blockRegion.tsx — BlockRegion: a thin scope FRAME with a
// real Block integral to its top-left corner, an optional free body, and an
// ordered list of arm rows. Props in, DOM out (docs/CONTROL-FLOW-PLAN.md
// §3.2); it imports no scene module and no canvas engine, so the same
// element renders under the DOM canvas, React Flow and tldraw unchanged.
//
// WHY "BlockRegion" and a composite rather than a frame with a slot (Zach,
// 2026-09-22: "Block Region is stanadlone component that composes the Block
// with a 'region'"): the corner IS a Block. Give it a `title` and this
// component draws that Block itself, `shape="region-corner"`, so the square
// junctions come with it. The Labeled Group is exactly that with nothing
// else (`blockRegion.labeledGroup.tsx`). A host that needs ports on the card
// still passes its own `BlockPort`-wrapped Block as `corner`, and gives that
// Block the same shape: the shape is the Block's, not the region's
// (block.tsx, `BlockShape`).
//
// ── ONE NODE, TWO PIECES OF PAINT (plan §2.A, Zach's "everything is a
//    block" made structural) ──────────────────────────────────────────
// A region is ONE scene node. The FRAME is how that node renders its
// SCOPE; the CORNER BLOCK is how it renders its INTERFACE. There is no
// second node, no head child, and the frame carries no value ports of its
// own — a loop's `Iterable`/`Iter` and a branch's conditions are ports on
// the corner card, resolved by exactly the same `[data-block-id]` ->
// `[data-port-id]` walk as any other block's.
//
// WHY the root and the frame carry `data-region-id` and NEVER
// `data-block-id`: `wireLayer.tsx`'s `resolveDot` takes the FIRST
// `[data-block-id="<id>"]` in document order (wireLayer.tsx:81). If the
// frame carried the region's id it would win that lookup, and every wire
// into the corner card would resolve against a box that owns no dot. The
// corner card owns the id; the frame owns the region id. The tempting
// alternative — stamping both and "letting the more specific one win" —
// cannot work, because document order, not specificity, is the rule.
//
// LOOK: React Flow UI's Labeled Group Node (`Pasted image 20260918192040.png`,
// the reference Zach named): a thin rounded frame with a transparent fill
// and a label chip INSIDE the frame at its top-left, sharing the frame's
// rounding there and square where it meets the frame. Ours is a whole
// Block rather than a text chip, which is the entire point.
//
// ── FIVE DRAWINGS, ONE COMPONENT (2026-09-19, `skin/regionVariants.ts`) ──
// Zach asked for five proposals for how a region could be drawn
// differently. They are NOT five components and not five props: every
// paint value below is a CSS custom property (`--bbox-region-*`) read with
// today's value as its `var()` fallback, and a variant is a block of those
// properties keyed on `data-bbox-region-variant` on any ancestor
// (`skin/regionVariants.css`, the skin.css mechanism). The two things CSS
// cannot drive — the arm header's height, which the pure layout twin must
// be told, and the fold chevron's `reveal`, which is a prop — come from
// the TS spec via `useRegionVariant`, keyed on the SAME attribute. So no
// variant is ever a fork of this file, and a consumer who never imports
// the CSS renders the pixels this component rendered before variants
// existed (`v1`).
//
// What every variant keeps, because Zach's ruling is not a variant axis:
// the corner block flush with the frame's top-left; its dots ON the frame
// edge and never clipped; arms stacked under it and folded by the chevron;
// the opaque card untouched.
//
// Pure: no React state beyond two measurements (the corner's box and the
// variant in force), no DOM outside its own subtree, no scene import (the
// `layering.test.ts` import wall).

import { useLayoutEffect, useState, type CSSProperties, type ReactNode } from "react";
import { flushSync } from "react-dom";

import { Bar } from "./bar";
import { Block, REGION_FRAME_RADIUS } from "./block";
import { BlockMembers, type BlockMember } from "./blockMembers";
import { FoldingChevron } from "./foldingChevron";
import {
  REGION_ARM_FADE_OPACITY,
  REGION_CORNER_WIDTH_PX,
  regionLayout,
  type RegionLayout,
} from "./blockRegion.layout";
import {
  DEFAULT_REGION_VARIANT,
  REGION_VARIANT_ATTR,
  REGION_VARIANTS,
  readRegionVariant,
  type RegionVariantId,
} from "../skin/regionVariants";

export type RegionKind = "loop" | "branch" | "group";
export type RegionView = "expanded" | "opaque";

export interface RegionArm {
  id: string;
  /** Free text, human readable — `if fast:`, `case "pet":`. Never code. */
  title: ReactNode;
  open: boolean;
  onOpenChange?(open: boolean): void;
  /** Absent is ACTIVE. Donor branchModel.ts:11-12 — "no active arm means
   *  every arm is active". */
  active?: boolean;
  /** Body height while open; remembered while folded (`regionLayout`). */
  bodyHeight?: number;
  members?: BlockMember[];
}

export interface BlockRegionProps {
  /** Stamped as `data-region-id` on the root AND the frame — never
   *  `data-block-id`. See this file's header. */
  id: string;
  kind?: RegionKind;
  view?: RegionView;
  /**
   * The corner card's title. With no `corner`, BlockRegion draws the card
   * itself: a header-only `Block`, `shape="region-corner"` while expanded and
   * a plain card while opaque, hugging its title. Rendered as authored.
   */
  title?: ReactNode;
  /**
   * The corner card, supplied whole — for a card with ports: a `BlockPort`
   * whose `id` IS this region's id, around a `Block` with
   * `shape="region-corner"`. Takes precedence over `title`. Omit both for a
   * bare scope with nothing in its corner.
   */
  corner?: ReactNode;
  /** Skip the measurement when a host already knows the corner's box. */
  cornerSize?: { w: number; h: number };
  width?: number;
  /** Omitted = hug (`regionLayout`). */
  height?: number;
  /** The free body a loop/group drops into — `BlockMembers layout="free"`. */
  members?: BlockMember[];
  arms?: RegionArm[];
  className?: string;
  style?: CSSProperties;
}

/** The frame's own border, px — the number the corner is pulled back by so
 *  the two borders sit on ONE line rather than doubling into a 2px rule.
 *  Every variant keeps this 1px of GEOMETRY (a variant may paint it
 *  transparent, never widen it), which is what keeps every row, member and
 *  dot exactly where it was under `v1`. */
const FRAME_BORDER_PX = 1;

/** The frame's shared top-left radius — the corner card's too, which is why
 *  it lives beside `Block`'s `"region-corner"` shape and is read from there:
 *  the frame and the card curve together only while they read one string. */
const FRAME_RADIUS = REGION_FRAME_RADIUS;

/**
 * The corner's measured box.
 *
 * WHY measured and not computed: the corner is a whole `Block` whose height
 * hugs its own header, ports and footer — there is no closed form for it
 * (the same reason `blockPort.tsx`'s `useBlockBands` measures rather than
 * derives). The first render has no box yet and falls back to
 * `{w: REGION_CORNER_WIDTH_PX, h: 0}`; `useLayoutEffect` corrects it BEFORE
 * the browser paints, so the guess is never on screen — the same
 * first-frame device `tldrawHost.tsx` uses, tightened one frame because
 * this measurement has no engine to wait for.
 */
function useCornerSize(given: { w: number; h: number } | undefined): {
  ref: (node: HTMLDivElement | null) => void;
  size: { w: number; h: number };
} {
  const [node, setNode] = useState<HTMLDivElement | null>(null);
  const [measured, setMeasured] = useState<{ w: number; h: number } | null>(null);
  const skip = given !== undefined;

  useLayoutEffect(() => {
    if (skip || !node) return;
    const read = () => {
      const rect = node.getBoundingClientRect();
      // Identity-preserving: a sub-pixel re-measure that says the same
      // thing must not re-render, or the observer feeds itself.
      setMeasured((previous) =>
        previous && Math.abs(previous.w - rect.width) < 0.5 && Math.abs(previous.h - rect.height) < 0.5
          ? previous
          : { w: rect.width, h: rect.height },
      );
    };
    read();
    const observer = new ResizeObserver(read);
    observer.observe(node);
    return () => observer.disconnect();
  }, [skip, node]);

  return { ref: setNode, size: given ?? measured ?? { w: REGION_CORNER_WIDTH_PX, h: 0 } };
}

/**
 * The variant in force for THIS region — the nearest ancestor carrying
 * `data-bbox-region-variant`, else `<html>`'s, else `v1`
 * (`readRegionVariant`).
 *
 * WHY it is measured off the DOM in a layout effect, like the corner, and
 * not passed as a prop or read from a context: the contract's switch is an
 * ATTRIBUTE (so the app's dropdown and Storybook's global are three lines
 * each, and CSS reads the same thing), and an attribute change re-renders
 * nothing here on its own. The CSS tokens follow it for free; the two
 * values that are not CSS — the header height the layout twin needs and
 * the chevron's `reveal` — follow it through the observer below, without
 * any React state outside this file. The first render assumes `v1` and the
 * layout effect corrects it before paint, the device `useCornerSize` uses.
 *
 * WHY the observer is shaped as it is — the failure it closes is a
 * HALF-SWITCHED region, CSS on the new drawing and layout/chevron on the
 * old (`RegionVariants.stories.tsx`'s `SwitchOnAncestor*` and
 * `SwitchNeverHalfPainted`, each red against the alternative named here):
 *   • It watches the WHOLE document (`subtree`), filtered to the one
 *     attribute — `<html>`'s dataset from an app dropdown, a wrapper
 *     written by hand, and a React-owned wrapper (the Storybook global)
 *     whether or not this region re-rendered with it. Observing only
 *     `<html>` (the first cut) left a nearer ancestor's switch unseen
 *     forever. The filter keeps it cheap: records exist only for this
 *     attribute, which changes when someone picks a drawing.
 *   • It applies the change with `flushSync`. Its callback is a microtask,
 *     and a plain `setState` from there is scheduled as a later TASK —
 *     after the browser has painted the new CSS over the old layout, one
 *     visible frame of jitter per switch. `flushSync` renders inside the
 *     same microtask checkpoint, before paint; when the resolved variant
 *     did not change (another subtree's switch) the same-value bail-out
 *     makes it a `closest()` walk and nothing else.
 */
function useRegionVariant(node: HTMLElement | null): RegionVariantId {
  const [variant, setVariant] = useState<RegionVariantId>(DEFAULT_REGION_VARIANT);
  useLayoutEffect(() => {
    if (!node) return;
    setVariant(readRegionVariant(node));
    const observer = new MutationObserver(() => {
      const next = readRegionVariant(node);
      flushSync(() => setVariant(next));
    });
    observer.observe(document.documentElement, { attributes: true, attributeFilter: [REGION_VARIANT_ATTR], subtree: true });
    return () => observer.disconnect();
  }, [node]);
  return variant;
}

function ArmRow({
  arm,
  row,
  index,
  chevron,
}: {
  arm: RegionArm;
  row: RegionLayout["arms"][number];
  index: number;
  chevron: "always" | "hover";
}) {
  const active = arm.active ?? true;
  return (
    <div
      data-slot="region-arm"
      data-arm-id={arm.id}
      data-open={String(row.open)}
      data-active={String(active)}
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: row.rowTop,
        height: row.bottom - row.rowTop,
        // WHY a single opacity token on the ROW and not per-element
        // styling: the donor fades "non-active arms, their Blocks and
        // their cables" with ONE number (branchModel.ts:38-39,
        // BRANCH_FADE_OPACITY = 0.18), and a row-level opacity carries the
        // arm's members with it for free. Cable fade is a follow-up — the
        // wires live in a sibling layer, not inside this box.
        opacity: active ? undefined : REGION_ARM_FADE_OPACITY,
      }}
    >
      {/*
        The arm's DECOR box — `v5`'s inset card, `v4`'s indent guide, nothing
        at all by default (`display: none`). WHY a real element and not a
        `::before`: this component is props in, DOM out, and a box the
        acceptance can measure (`RegionVariants.stories.tsx` reads its rect)
        has to be in the DOM. It is absolutely positioned and comes FIRST,
        and the header and body are positioned after it, so it paints
        BEHIND both in DOM order — no z-index, which the paint-order
        invariant (paintOrder.ts) would otherwise have to account for. The
        row's own box never moves for it: `expectArmsStacked` and every
        member's authored position hold in all five drawings.
      */}
      <div
        data-slot="region-arm-decor"
        aria-hidden
        style={{
          display: "var(--bbox-region-arm-decor-display, none)",
          position: "absolute",
          inset: "var(--bbox-region-arm-decor-inset, 0px)",
          width: "var(--bbox-region-arm-decor-width, auto)",
          borderStyle: "solid",
          borderWidth: "var(--bbox-region-arm-decor-stroke-widths, 0px)",
          borderColor: "var(--bbox-region-arm-decor-stroke, var(--border))",
          borderRadius: "var(--bbox-region-arm-decor-radius, 0px)",
          background: "var(--bbox-region-arm-decor-fill, transparent)",
          pointerEvents: "none",
        }}
      />
      <div
        data-slot="region-arm-header"
        style={{
          // Positioned so it paints after the decor box above (DOM order
          // among positioned boxes), never under it.
          position: "relative",
          height: row.bodyTop - row.headerTop,
          paddingLeft: "var(--bbox-region-arm-header-inset, 0px)",
          // `v3`'s band; transparent otherwise.
          background: "var(--bbox-region-arm-header-fill, transparent)",
          // A divider between rows only, never above the first — the
          // donor's own `dividerY: index === 0 ? null : rowTop`
          // (branchModel.ts). `v3`/`v4`/`v5` set its width to 0.
          borderTop: index > 0 ? "var(--bbox-region-arm-divider-width, 1px) solid var(--bbox-region-arm-divider-stroke, var(--border))" : undefined,
          // `v2`'s rule under every header; 0 otherwise.
          borderBottom: "var(--bbox-region-arm-header-rule-width, 0px) solid var(--bbox-region-arm-header-rule-stroke, var(--border))",
        }}
      >
        <Bar
          size="sm"
          // WHY `100%` and not the rung's own 28px: the header row is the
          // variant's height (26 for the bracket, 32 for the ruled), and
          // the strip fills it so the chevron and title are centred in the
          // row rather than top-biased by whatever the difference is.
          style={{ height: "100%" }}
          left={
            <>
              <FoldingChevron open={row.open} onClick={() => arm.onOpenChange?.(!row.open)} reveal={chevron} />
              <span
                data-slot="region-arm-title"
                className="truncate"
                // No fallbacks on purpose: an UNSET token is invalid at
                // computed-value time, and for these four inherited
                // properties that means `inherit` — the Bar's own text.
                // That is how `v1` says "leave the title alone" without
                // this file naming a font it does not own
                // (regionVariants.ts's own note on `initial`).
                style={{
                  fontSize: "var(--bbox-region-arm-title-size)",
                  fontWeight: "var(--bbox-region-arm-title-weight)",
                  fontFamily: "var(--bbox-region-arm-title-font)",
                  color: "var(--bbox-region-arm-title-color)",
                }}
              >
                {arm.title}
              </span>
            </>
          }
        />
      </div>
      {row.open && (
        // WHY the body LEAVES THE DOM when folded rather than collapsing to
        // `height: 0`: `expectArmsStacked` measures a folded arm as "no
        // body", and a zero-height box that still contains members would
        // keep them hit-testable and focusable while invisible — a folded
        // arm has to be genuinely absent, not merely unpainted.
        <div
          data-slot="region-arm-body"
          style={{ position: "relative", height: row.bodyHeight }}
        >
          <BlockMembers
            layout="free"
            members={arm.members ?? []}
            gap={0}
            gutter={0}
            insetBackground="none"
            showMembers
            showCards={false}
          />
        </div>
      )}
    </div>
  );
}

/**
 * The corner card BlockRegion draws for itself when it is given a `title` and
 * no `corner`: a header-only Block that hugs its title.
 *
 * WHY no header divider: the header is the whole card, so its rule would sit
 * on the card's own bottom border and double it. WHY it hugs instead of taking
 * `REGION_CORNER_WIDTH_PX`: this is the Labeled Group's label, and React Flow's
 * reference label is as wide as its text. A region whose card carries ports
 * passes its own sized card as `corner`.
 */
function TitleCorner({ title, opaque }: { title: ReactNode; opaque: boolean }) {
  return (
    <Block
      header={title}
      showHeaderDivider={false}
      shape={opaque ? "card" : "region-corner"}
      style={{ width: "max-content" }}
    />
  );
}

export function BlockRegion({
  id,
  kind = "group",
  view = "expanded",
  title,
  corner: givenCorner,
  cornerSize,
  width,
  height,
  members,
  arms,
  className,
  style,
}: BlockRegionProps) {
  const corner = givenCorner ?? (title === undefined ? null : <TitleCorner title={title} opaque={view === "opaque"} />);
  const [root, setRoot] = useState<HTMLDivElement | null>(null);
  const variant = useRegionVariant(root);
  const spec = REGION_VARIANTS[variant];
  const { ref: cornerRef, size } = useCornerSize(cornerSize);
  const layout = regionLayout({
    width: width ?? REGION_CORNER_WIDTH_PX,
    ...(height === undefined ? null : { height }),
    corner: size,
    armHeaderPx: spec.arms.headerPx,
    arms: (arms ?? []).map((arm) => ({
      id: arm.id,
      open: arm.open,
      ...(arm.bodyHeight === undefined ? null : { bodyHeight: arm.bodyHeight }),
    })),
  });

  /** Does THIS region paint the header rule at all? See the rule's own WHY
   *  below for the two halves. Computed here so the frame and any future
   *  reader agree on one answer. */
  const drawsHeaderRuleHere = kind !== "loop" && layout.arms.length > 0;

  const rootProps = {
    "data-slot": "region",
    "data-region-id": id,
    "data-region-kind": kind,
    "data-region-view": view,
    // Informational — which drawing this region resolved to. NOT the switch
    // attribute (`data-bbox-region-variant`), which stays the host's to
    // stamp: writing it here would shadow every ancestor's choice.
    "data-region-variant": variant,
  } as const;

  // P5, opaque: the root wraps ONLY the corner card — the host's, or with
  // `title` the one `TitleCorner` draws, which turns itself back into a plain
  // `card` here. No frame, no arms, no body — the whole point of the view is
  // that the inside is not drawn. The card's own ports and footer are the
  // host's business (`nodeViews.tsx`), which is why this branch renders
  // `corner` untouched — and why no variant token is read here: the opaque
  // card reads the same in every drawing by design.
  if (view === "opaque") {
    return (
      <div {...rootProps} ref={setRoot} className={className} style={{ width: "max-content", ...style }}>
        {corner}
      </div>
    );
  }

  return (
    <div
      {...rootProps}
      ref={setRoot}
      className={className}
      style={{
        position: "relative",
        width: "max-content",
        // The fill THIS frame paints, captured at the root: the token as
        // inherited from outside this region. The frame below re-declares
        // `--bbox-region-frame-fill` for its DESCENDANTS as the variant's
        // nested fill, so a region inside this one reads "one tone deeper"
        // while this frame itself still reads the outer value — the
        // capture on the root is what breaks the self-reference.
        ...({ "--bbox-region-fill-here": "var(--bbox-region-frame-fill, transparent)" } as CSSProperties),
        ...style,
      }}
    >
      <div
        data-slot="region-frame"
        data-region-id={id}
        style={{
          position: "relative",
          width: layout.width,
          height: layout.height,
          // Four widths so the bracket (`v4`) can open the right and the
          // bottom; every variant keeps the top and the left at
          // FRAME_BORDER_PX, the corner card's home.
          borderWidth: `var(--bbox-region-frame-stroke-widths, ${FRAME_BORDER_PX}px)`,
          borderStyle: "var(--bbox-region-frame-dash, solid)",
          borderColor: "var(--bbox-region-frame-stroke, var(--border))",
          borderRadius: `var(--bbox-region-frame-radii, ${FRAME_RADIUS})`,
          // Transparent by default, so a cable routed UNDER the frame still
          // reads, and `visible` so the corner card's wall dots may
          // straddle the frame's own edge instead of being clipped off at
          // it (plan §9's "no clip" default — and Zach's `115050`, where
          // the app's frame cut a port in half).
          background: "var(--bbox-region-fill-here)",
          overflow: "visible",
          // For descendants only (see the root's note): a nested frame
          // reads the variant's nested fill, or this frame's own fill when
          // the variant draws no nesting contrast.
          ...({ "--bbox-region-frame-fill": "var(--bbox-region-nested-fill, var(--bbox-region-fill-here))" } as CSSProperties),
        }}
      >
        {/*
          `v2`'s header RULE — the line Zach pointed at in `Pasted image
          20260919115353.png`: the corner card's bottom edge continued across
          the full width of the frame. Rendered BEFORE the corner so the
          card paints over its left run, and placed on the card's own bottom
          border row — the card is pulled back by FRAME_BORDER_PX, so its
          last pixel row is `corner.h - 2 * FRAME_BORDER_PX` in the frame's
          padding box — so the two are one line, not two a pixel apart.
          `display: none` unless the variant turns it on.

          WHY it is ALSO gated on having arms (Zach, 2026-09-20, on v9: "For
          loop and while loops like this no inside lines", against a Branch
          shown WITH them): this rule is the bottom edge of the HEADER BAND —
          it exists to divide the header from the titled arm rows underneath.
          A `for`/`while` region has no arms at all (`FOR_LOOP_PRESET.arms:
          []`; its body is the frame itself), so under v2/v9/v10 — the three
          variants that set `--bbox-region-header-rule-display: block` — it
          was drawing a full-width line across an empty body, dividing
          nothing from nothing.

          BOTH halves of the predicate are load-bearing. `arms.length > 0`
          is the honest test — the arm rows are what the line separates, so a
          branch that lost its arms loses the rule with them. `kind !== "loop"`
          is the belt: a loop must never draw it even holding malformed data,
          and that case is REAL, not hypothetical — `variants.smoke.test.tsx`'s
          own `regionOfKind` helper mints every kind with one `body` arm, so an
          arms-only gate would have kept painting the rule on the very for/while
          regions Zach is complaining about. A future arm-bearing kind (match /
          case) still keeps its rule, because only `"loop"` is excluded.

          The tempting alternative — scoping the token in `regionVariants.css`
          off the already-stamped `[data-region-kind]` — cannot work: this
          display is an INLINE style, so it outranks any stylesheet rule no
          matter how specific.
        */}
        <div
          data-slot="region-header-rule"
          aria-hidden
          style={{
            display: drawsHeaderRuleHere ? "var(--bbox-region-header-rule-display, none)" : "none",
            position: "absolute",
            left: 0,
            right: 0,
            top: layout.corner.h - 2 * FRAME_BORDER_PX,
            height: FRAME_BORDER_PX,
            background: "var(--bbox-region-header-rule-stroke, var(--border))",
            pointerEvents: "none",
          }}
        />
        <div
          ref={cornerRef}
          data-slot="region-corner"
          style={{
            position: "absolute",
            // Pulled back by the frame's border so the two borders land on
            // one line: the corner reads as PART of the frame, which is the
            // whole Labeled Group Node look.
            top: -FRAME_BORDER_PX,
            left: -FRAME_BORDER_PX,
            width: "max-content",
          }}
        >
          {corner}
        </div>
        <div
          data-slot="region-body"
          style={{ position: "absolute", left: 0, top: layout.body.y, width: "100%", height: layout.body.h }}
        >
          <BlockMembers
            layout="free"
            members={members ?? []}
            gap={0}
            gutter={0}
            insetBackground="none"
            showMembers
            showCards={false}
          />
        </div>
        {layout.arms.map((row, index) => (
          <ArmRow key={row.id} arm={(arms ?? [])[index]} row={row} index={index} chevron={spec.arms.chevron} />
        ))}
      </div>
    </div>
  );
}

/**
 * bbox-ui EditableText layout — the portable geometry of the text-leaf.
 *
 * EditableText's own size ladder, deliberately NOT `layout.ts`'s `TEXT_SIZES`
 * (frozen for T1) and NOT `Glyph`'s or `Port`'s own independent ladders —
 * see docs/T1-SPEC.md §0 on why three components each get their own 18px
 * "small" rung rather than one shared file. React-free, engine-free, same
 * discipline as `layout.ts`.
 *
 * PROVENANCE: OURS, AD HOC. NO PRIOR ART IS CLAIMED, and this file has no
 * donor — stated explicitly rather than left as an absence, because an
 * uncited file is ambiguous between "written here" and "nobody wrote down
 * where this came from", and only one of those is true.
 *
 * There is also no algorithm here to have prior art FOR. Every export is a
 * lookup table or a total `Record` over a string union: the size ladder, the
 * three font stacks, and the two align→flex maps. The one function with a
 * rule in it, `editableTextFontPx`, is a single ternary. The CSS values on
 * the right-hand side of those Records (`flex-start`/`center`/`flex-end`)
 * are of course the CSS Flexbox spec's, but this file does not implement
 * them — it names them and hands them to the browser, which is not a
 * citation-bearing act. The reason the tables are TOTAL Records rather than
 * ternaries is a real decision and it is documented at each seam below.
 */

/** EditableText's own ladder. Values match the board's own Text Size row. */
export const EDITABLE_TEXT_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
// WHY `EditableTextSize` widens by union rather than `EDITABLE_TEXT_SIZES` growing a
// fifth rung: "custom" has no single px value — it is the ESCAPE from the
// named ladder into `sizePx`, so it cannot live in a `Record<name, px>` the
// way sm/md/lg/xl do. `editableTextFontPx` below is the one place that resolves
// either shape back to a number. See docs/TEXTBOX-EDITING-SPEC.md §1.
export type EditableTextSize = keyof typeof EDITABLE_TEXT_SIZES | "custom";

/** The font-size in px for a given `size`/`sizePx` pair — the one function
 * that knows "custom" escapes the named ladder. `sizePx` is ignored for the
 * four named rungs, exactly like `font`/`align` ignore props that don't
 * apply to them. */
export function editableTextFontPx(size: EditableTextSize, sizePx: number): number {
  return size === "custom" ? sizePx : EDITABLE_TEXT_SIZES[size];
}

// WHY the array is the source and the type is derived: annotating the field
// table stopped the SCHEMA advertising a value the component cannot render,
// but not the reverse — widening the union and adding its stack left the
// panel silently offering three of four fonts with the suite green. With one
// runtime array behind both, a test can pin the field's options to it and
// catch growth in either direction. Same shape as BLOCK_ORIENTATIONS.
export const EDITABLE_TEXT_FONTS = ["sans", "sketch", "mono"] as const;
export type EditableTextFont = (typeof EDITABLE_TEXT_FONTS)[number];
export const EDITABLE_TEXT_FONT_STACKS: Record<EditableTextFont, string> = {
  sans: 'ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif',
  sketch: '"Segoe Print", "Bradley Hand", cursive',
  mono: 'ui-monospace, "SF Mono", Menlo, Consolas, monospace',
};

type FlexPlacement = "flex-start" | "center" | "flex-end";

// WHY total Records rather than the ternaries these replace: deriving the
// union from the array made widening it reach the panel automatically, which
// is what we wanted — but a ternary has a fall-through, so a new member
// arrived as a live segment that silently rendered `center`, typecheck clean
// and every test green. A total Record is what makes the array the real
// source: adding a member is a compile error until someone says where it
// lays out. The same shape as EDITABLE_TEXT_FONT_STACKS, which is why `font`
// already failed loudly and these two did not.
export const EDITABLE_TEXT_VERTICAL_ALIGNS = ["top", "middle", "bottom"] as const;
export type EditableTextVerticalAlign = (typeof EDITABLE_TEXT_VERTICAL_ALIGNS)[number];
export const EDITABLE_TEXT_ALIGN_ITEMS: Record<EditableTextVerticalAlign, FlexPlacement> = {
  top: "flex-start",
  middle: "center",
  bottom: "flex-end",
};
export function editableTextAlignItems(align: EditableTextVerticalAlign): FlexPlacement {
  return EDITABLE_TEXT_ALIGN_ITEMS[align];
}

export const EDITABLE_TEXT_HORIZONTAL_ALIGNS = ["left", "middle", "right"] as const;
export type EditableTextHorizontalAlign = (typeof EDITABLE_TEXT_HORIZONTAL_ALIGNS)[number];
export const EDITABLE_TEXT_JUSTIFY_CONTENT: Record<EditableTextHorizontalAlign, FlexPlacement> = {
  left: "flex-start",
  middle: "center",
  right: "flex-end",
};
export function editableTextJustifyContent(justify: EditableTextHorizontalAlign): FlexPlacement {
  return EDITABLE_TEXT_JUSTIFY_CONTENT[justify];
}

import type { ComponentProps } from "react";
import { ChevronRight } from "lucide-react";

import { cn } from "../lib/utils";

/**
 * src/components/foldingChevron.tsx — the standalone trigger built on top of
 * `Collapsible` (collapsible.tsx). A single Lucide `ChevronRight` whose
 * rotation is driven by `open` via inline `transform`: folded (closed)
 * reads as ▶, open rotates 90° to read as ▼ — matching the sketch's plain
 * triangle either way. `Block`'s actual body/footer wiring lives at the
 * STORY level (src/components/Block.stories.tsx's `CollapsibleHeader`), not
 * here and not as a new `Block` prop — this component only knows how to
 * show its own open/closed state and fire a click.
 */
export interface FoldingChevronProps extends Omit<ComponentProps<"button">, "onClick"> {
  open: boolean;
  onClick: () => void;
  /**
   * WHY this prop exists (Zach: "add a control option to the drop down
   * chevron so that it's borderless and just appears on hover, however
   * when its collapsed then it always shows"): `"always"` is the default
   * so every existing caller (Bar/Block header wiring) is unchanged.
   * `"hover"` starts the chevron invisible and reveals it on `group-hover`
   * of its surrounding region — CSS-only (`group`/`group-hover`), not JS
   * hover state, so reveal never depends on a render round-trip and keeps
   * working under `prefers-reduced-motion` — chosen over a JS
   * `onMouseEnter` on the region because the region (a `Bar`) is a
   * separate component this file doesn't own the JS lifecycle of; the CSS
   * relationship is the only coupling that doesn't require threading hover
   * state as a prop through Bar. The layout box is never removed (only
   * `opacity` toggles), so revealing it never shifts sibling content.
   */
  reveal?: "always" | "hover";
}

export function FoldingChevron({
  open,
  onClick,
  reveal = "always",
  className,
  style,
  ...props
}: FoldingChevronProps) {
  // WHY collapsed always wins regardless of `reveal` (Zach's explicit
  // sentence): a folded section has to keep advertising that it can be
  // expanded — hiding its only trigger behind a hover a collapsed user has
  // no reason to attempt would make the section look permanently empty.
  const hoverHidden = reveal === "hover" && open;
  const alwaysForced = reveal === "hover" && !open;
  return (
    <button
      type="button"
      data-slot="folding-chevron"
      aria-expanded={open}
      onClick={onClick}
      className={cn(
        "inline-flex size-6 shrink-0 items-center justify-center text-muted-foreground transition-colors hover:text-foreground",
        // `reveal="always"` keeps the original hover chip; `"hover"` is
        // borderless in every state (open-collapsed-forced-visible
        // included) — the background pill is what "always" and "hover"
        // actually differ on visually once the glyph itself is showing.
        reveal === "always" && "hover:bg-muted",
        hoverHidden &&
          "opacity-0 transition-opacity group-hover:opacity-100 group-focus-within:opacity-100 focus-visible:opacity-100",
        alwaysForced && "opacity-100",
        className,
      )}
      // The skin seam (src/skin/skin.ts + skin.css) — `rounded-md` moved
      // off the class list and onto here; `var(--radius-md)` is exactly
      // what it resolved to, so a consumer who never imports skin.css is
      // byte-identical. It paints only once the hover pill does, but the
      // property is set unconditionally, same as every other radius call
      // site in this port.
      style={{ borderRadius: "var(--bbox-skin-radius, var(--radius-md))", ...style }}
      {...props}
    >
      <ChevronRight
        className="size-4 transition-transform duration-150"
        style={{ transform: open ? "rotate(90deg)" : "rotate(0deg)" }}
      />
    </button>
  );
}

/**
 * src/components/glyph.layout.ts — ported by value from
 * packages/bbox-ui/src/glyph.layout.ts (Glyph v2, docs/GLYPH-PLAN.md's
 * contract). Same size ladder and override-vs-preset rule; this app has no
 * `layout.ts`/`TEXT_SIZES` of its own to stay independent of, but the
 * ladder is kept in its own file anyway so `glyph.tsx` matches its source
 * shape 1:1 for anyone diffing the two later.
 *
 * DONOR LINES (read 2026-09-17; the donor is 53 lines and lives in this
 * same repo, so this is a `diff` away, not an archaeology dig):
 *   • `glyph.layout.ts:11`    `GLYPH_SIZES` — same four rungs, same values.
 *   • `glyph.layout.ts:20-43` the two interfaces.
 *   • `glyph.layout.ts:45-52` `glyphFootprint`, including the `!== undefined`
 *     rule restated below. Arithmetic unchanged.
 *
 * NO PRIOR ART IS CLAIMED, and none applies: the "ladder plus override"
 * rule and the square `size + 2*padding` footprint are this repo's own
 * product decisions, not an algorithm. There is nothing here to cite but
 * the donor.
 */
export const GLYPH_SIZES = { sm: 18, md: 24, lg: 36, xl: 44 } as const;
export type GlyphSize = keyof typeof GLYPH_SIZES;
export const GLYPH_SIZE_NAMES: Record<GlyphSize, string> = {
  sm: "Small",
  md: "Medium",
  lg: "Large",
  xl: "Extra Large",
};

export interface GlyphFootprintInput {
  sizePreset?: GlyphSize;
  /** px override — when given, wins over `sizePreset`. */
  size?: number;
  padding?: number;
}

export interface GlyphFootprint {
  /** Resolved side length of the glyph itself, px. */
  size: number;
  padding: number;
  /** Outer box a host places on canvas — `size + 2*padding`, square. */
  w: number;
  h: number;
}

/**
 * The override-vs-preset size rule, in one place. `size` absent/undefined
 * is NOT the same as `size: 0` — an explicit 0 is a real override, so this
 * checks `!== undefined`, never falsy/`??`, to keep that case distinguishable.
 */
export function glyphFootprint({
  sizePreset = "sm",
  size,
  padding = 0,
}: GlyphFootprintInput): GlyphFootprint {
  const resolvedSize = size !== undefined ? size : GLYPH_SIZES[sizePreset];
  const outer = resolvedSize + 2 * padding;
  return { size: resolvedSize, padding, w: outer, h: outer };
}

"use client";

// src/components/highlighter.tsx — NET NEW (docs/INVALID-STATES-PLAN.md §1,
// §4, §5), renamed from diagnostic.tsx per Zach's mid-run feedback on the
// proposal report: "I do wonder if visual language wise if we should just
// borrow from jointjs and do the highlighting... I think we can basically
// just copy it as well... Perhaps we can just borrow their terminology.
// Highlighters I think is right." The DATA stays named `Diagnostic` — a
// diagnostic is the finding, a highlighter is how it gets drawn, and that
// split is worth keeping distinct in the names. This file carries: the
// closed severity set, the `Diagnostic` shape (a LIST with a stable id —
// see this file's own history for why), the severity->token map, the
// three `HighlighterKind`s JointJS's own docs page catalogues (`stroke`,
// `mask`, and this kit's own pre-existing `halo`/glow treatment — Appendix
// A's own table maps JointJS's five highlighter types onto this plan's
// equivalents), the wavy/dotted underline helper every text-bearing mark
// uses, and the one genuinely new interactive composition —
// `DiagnosticFlag`.
//
// WHY `diagnostics` is a LIST with a stable `id`, not the scalar the plan's
// §1 first drafted: a producer that pre-merges N findings into one has
// already destroyed the rest before this file ever sees them, and §5
// promises a Popover with "the full anatomy" — it can only show what it's
// handed. Zach's own ruling overturned the scalar mid-implementation
// (verbatim: "a peer session that read the same docs reached the same
// conclusion... the deciding detail is the count: Vyuh's status badges and
// maxGraph's containsValidationErrors both show an error count on the
// badge, and you cannot render a count from a scalar"), and the plan doc
// was amended to match. Confirmed again in the SAME mid-run feedback that
// renamed this file: "this idea to support multiple marks... super true in
// case we need to indicate various problems! love that." The CHROME still
// reads only `max(severity)` (see `maxDiagnosticSeverity` below) — one
// highlighter, one underline — so the "visual calm" argument for a scalar
// is preserved at the paint layer; only identity and the popover's list
// are plural.
//
// WHY `stroke` is the DEFAULT `HighlighterKind`, with `mask` and `halo`
// kept as siblings rather than one replacing another: Zach's own words on
// the report were a QUESTION, not a ruling — "perhaps that's clearer than
// the shadow drop..?" — so this is a variants-with-a-recommended-default
// delivery (his own standing preference), not a swap. See
// `HighlighterKind`'s own doc below for what each kind means and where it
// is implemented.

import { Info, OctagonX, TriangleAlert, type LucideIcon } from "lucide-react";
import type { CSSProperties, ReactElement, ReactNode } from "react";

import { cn } from "../lib/utils";
import { Badge } from "./badge";
import { Popover, PopoverContent, PopoverTrigger } from "./popover";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "./tooltip";

/* ------------------------------------------------------------------ */
/* The vocabulary — §1                                                 */
/* ------------------------------------------------------------------ */

/** The closed set. Three members, like the skin table's fixed 13 tokens
 *  (skin.ts:89) — an open-ended set of marks degenerates into a pile of
 *  per-callsite overrides. */
export type DiagnosticSeverity = "error" | "warning" | "info";

export const DIAGNOSTIC_SEVERITIES: DiagnosticSeverity[] = ["error", "warning", "info"];

export interface Diagnostic {
  /**
   * Stable, producer-owned. Appendix B records the cost of not having one:
   * maxGraph's `setCellWarning(cell, null)` deletes EVERY overlay on the
   * cell, and per-item identity is what prevents that. It is also what
   * lets a host diff the list per item instead of rebuilding it (JointJS's
   * `list` highlighter skips `createListItem` for unchanged entries).
   */
  id: string;
  severity: DiagnosticSeverity;
  /** One-line human explanation — the FR's "text explanation for what the
   *  issue is". Optional: a mark can render before its prose exists. */
  message?: string;
  /** Rule id — VS Code's `Ruff(F407)` slot. */
  code?: string;
}

const SEVERITY_RANK: Record<DiagnosticSeverity, number> = { error: 0, warning: 1, info: 2 };

/**
 * One mark, N messages: every mark-bearing component's CHROME (the halo,
 * the glow, the underline, the backdrop) is painted once at the worst
 * severity present — never a fifth `state`, never a per-finding stack of
 * paint layers. `undefined` for an absent or empty list, never persisted —
 * the same contract as `received` (appearance.ts) and `dimmed`/`hinting`
 * (host-computed, re-derived every render).
 */
export function maxDiagnosticSeverity(diagnostics?: readonly Diagnostic[]): DiagnosticSeverity | undefined {
  if (!diagnostics || diagnostics.length === 0) return undefined;
  return diagnostics.reduce<DiagnosticSeverity>(
    (worst, d) => (SEVERITY_RANK[d.severity] < SEVERITY_RANK[worst] ? d.severity : worst),
    diagnostics[0].severity,
  );
}

/* ------------------------------------------------------------------ */
/* Tokens — §2. Ported, not invented: packages/bbox-ui/src/theme.css:28-31 */
/* / :79-89 — see src/globals.css's own port of these three.            */
/* ------------------------------------------------------------------ */

/**
 * severity -> CSS colour. `error` alone carries a fallback (`--destructive`
 * — every shadcn theme defines it), per §2's own table; `warning`/`info`
 * need none because this kit always ports the two tokens that back them
 * (src/globals.css).
 */
export function diagnosticColorVar(severity: DiagnosticSeverity): string {
  switch (severity) {
    case "error":
      return "var(--bbox-danger, var(--destructive))";
    case "warning":
      return "var(--bbox-warning)";
    case "info":
      return "var(--bbox-accent)";
  }
}

/* ------------------------------------------------------------------ */
/* HighlighterKind — Appendix A's JointJS table, Zach's mid-run ask:     */
/* "borrow their terminology... they have both the stroke and also the  */
/* mask... we can support both!"                                        */
/* ------------------------------------------------------------------ */

/**
 * How a highlighter draws itself, per JointJS's own vocabulary
 * (docs/INVALID-STATES-PLAN.md Appendix A's table — `dia.HighlighterView`'s
 * five types, of which this kit implements the three that apply to marking
 * an already-drawn element rather than restyling its own fill/class):
 *
 * - `"stroke"` — a crisp outline traced at a fixed offset from the
 *   element's own silhouette. JointJS's own docs call this "the same
 *   outline, cheaper and less precise" than `mask`: on a shape with
 *   corners, an offset outline drawn at the ORIGINAL corner radius is not
 *   truly equidistant at the corners (the offset silhouette should grow
 *   its OWN radius by the offset amount, and a cheap implementation
 *   usually does not bother). The DEFAULT kind — Zach, reacting to the
 *   report's drop-shadow halo: "I do wonder if visual language wise if we
 *   should just borrow from jointjs and do the highlighting.. perhaps
 *   that's clearer than the shadow drop..?" — a question, not a ruling,
 *   which is why `halo` below is kept, not deleted.
 * - `"mask"` — the equidistant version: JointJS reaches for real SVG
 *   masking to get a genuinely parallel outline around an arbitrary
 *   silhouette, at a real performance cost, which is exactly why they
 *   document it as the pricier alternative to `stroke`. Appendix B's own
 *   finding is the load-bearing citation for how this kit implements it:
 *   "`mask` with `deep: true` falls back to `getBoundingClientRect()` when
 *   the target is HTML inside a `foreignObject`" — every component this
 *   axis marks is plain HTML, not an SVG silhouette, so this kit's `mask`
 *   is ALWAYS a bounding-rect technique, never a pixel-traced one, matching
 *   JointJS's own documented HTML fallback rather than overbuilding a
 *   silhouette tracer nothing here needs. Concretely: for a rounded
 *   rectangle (`Block`), the equidistant offset of a rounded rect by `d` is
 *   exactly a rounded rect with the SAME straight edges offset by `d` and
 *   the corner radius increased by `d` (the Minkowski sum of a rounded
 *   rectangle and a disc) — `highlighterMaskFrameStyle` below is that
 *   arithmetic, not a literal `<mask>` element, because the bounding-rect
 *   case never needs one. For a shape with no corners at all (`Port`'s
 *   circle), the equidistant offset of a circle is trivially a larger
 *   circle — `stroke` and `mask` are the IDENTICAL geometry there, and
 *   `Port` says so rather than drawing two indistinguishable rings.
 * - `"halo"` — this kit's own pre-existing treatment (a soft box-shadow
 *   ring on `Port`, a glow prepended to `Block`'s shadow list, a
 *   translucent backdrop under `Trace`): what the proposal report showed
 *   Zach before this feedback. Not JointJS vocabulary — kept as the third
 *   sibling because he questioned it, he did not reject it.
 */
export type HighlighterKind = "stroke" | "mask" | "halo";

export const HIGHLIGHTER_KINDS: HighlighterKind[] = ["stroke", "mask", "halo"];

/** Zach's own lean, from the report feedback (see `HighlighterKind`'s own
 *  doc) — every mark-bearing component defaults here unless a story is
 *  deliberately demonstrating a different kind. */
export const DEFAULT_HIGHLIGHTER_KIND: HighlighterKind = "stroke";

/**
 * The `stroke` kind for a DOM rectangle (`Block`): a plain CSS `outline`,
 * offset outward from the border box. Cheap and browser-native — modern
 * Chromium/Firefox already clip an `outline`'s corners to follow the
 * element's OWN `border-radius`, but at the SAME radius the box itself
 * has, which is exactly JointJS's "less precise" than `mask`: the outline
 * stops being truly equidistant the moment the box has any radius at all.
 * `offsetPx` is the gap between the box's own border and the drawn line.
 */
export function highlighterStrokeOutlineStyle(color: string, offsetPx: number, widthPx = 2): CSSProperties {
  return {
    outline: `${widthPx}px solid ${color}`,
    outlineOffset: offsetPx,
  };
}

/**
 * The `mask` kind for a DOM rectangle — see `HighlighterKind`'s own doc
 * for the Minkowski-sum reasoning. A sibling frame, sized `offsetPx`
 * larger on every side (`inset: -offsetPx`) so it never affects the
 * marked element's own layout box, with `radiusCss` (the SAME
 * `var(--bbox-skin-radius, ...)` chain the element's own corner reads)
 * grown by exactly `offsetPx` — `outline-offset` cannot do this (it
 * cannot touch `border-radius`), which is the whole reason this needs a
 * second element rather than one CSS property on the original.
 */
export function highlighterMaskFrameStyle(color: string, offsetPx: number, radiusCss: string, widthPx = 2): CSSProperties {
  return {
    position: "absolute",
    inset: -offsetPx,
    borderRadius: `calc(${radiusCss} + ${offsetPx}px)`,
    border: `${widthPx}px solid ${color}`,
    pointerEvents: "none",
  };
}

/* ------------------------------------------------------------------ */
/* The underline helper — §5's EditableText/LabeledPort/ValueCapsule row */
/* ------------------------------------------------------------------ */

/**
 * The one shared recipe behind "wavy underline, resting text" (§7's stock-
 * parts table: plain CSS `text-decoration`, no library). `error`/`warning`
 * wear a wavy line; `info` a dotted one — the same split §5 draws between a
 * halo and nothing, restated in the underline's own vocabulary.
 */
export function diagnosticUnderlineStyle(severity: DiagnosticSeverity): CSSProperties {
  return {
    textDecorationLine: "underline",
    textDecorationStyle: severity === "info" ? "dotted" : "wavy",
    textDecorationColor: diagnosticColorVar(severity),
    // Thickened slightly so the mark reads as deliberate at body-text sizes
    // rather than as a stray browser-default decoration.
    textDecorationThickness: "1.5px",
    textUnderlineOffset: "2px",
  };
}

/* ------------------------------------------------------------------ */
/* DiagnosticTooltip — the hover half of §5's interaction contract:    */
/* "hover any marked text/dot -> Tooltip with message + code (no       */
/* actions)". A thin wrapper, not a new visual: absent/empty           */
/* `diagnostics` renders `children` completely untouched, so a mark-   */
/* bearing component pays zero DOM cost at rest (same contract as      */
/* `Port`'s own `showHitRegion`/`hinting` — geometry identical on or   */
/* off).                                                                */
/* ------------------------------------------------------------------ */

export interface DiagnosticTooltipProps {
  diagnostics?: readonly Diagnostic[];
  /** The marked element itself — becomes the Tooltip's trigger via Base
   *  UI's `render` merge (the same pattern `Tooltip.stories.tsx`'s
   *  `OnIconButton` story already uses for a real button). */
  children: ReactElement;
}

export function DiagnosticTooltip({ diagnostics, children }: DiagnosticTooltipProps): ReactElement {
  if (!diagnostics || diagnostics.length === 0) return children;
  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger render={children} />
        <TooltipContent side="top">
          <div data-slot="diagnostic-tooltip-body" className="flex flex-col gap-1">
            {diagnostics.map((d) => (
              <div key={d.id} className="flex items-center gap-1.5">
                {d.code ? <span className="opacity-70">{d.code}</span> : null}
                <span>{d.message ?? d.severity}</span>
              </div>
            ))}
          </div>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
}

/* ------------------------------------------------------------------ */
/* DiagnosticFlag — §4's one genuinely-new interactive composition:    */
/* the anchored corner chip, wired as a Popover trigger. Message/code/ */
/* actions/footer is the click half of §5's contract; the hover half   */
/* lives on whatever it is attached to, via `DiagnosticTooltip` above. */
/* ------------------------------------------------------------------ */

const SEVERITY_ICON: Record<DiagnosticSeverity, LucideIcon> = {
  error: OctagonX,
  warning: TriangleAlert,
  info: Info,
};

/** The chip's own diameter, px — small enough to straddle a Block's corner
 *  or ride a LabeledPort's secondary slot without dominating either. */
export const DIAGNOSTIC_FLAG_SIZE_PX = 18;

export interface DiagnosticFlagProps {
  /** Non-empty — a caller renders no flag at all when the list is empty;
   *  "nothing" is the mark-bearing component's own job (§5's own table),
   *  not this component's. */
  diagnostics: Diagnostic[];
  /** The host's own follow-up controls, inside the popover body — VS
   *  Code's action button. Absent renders none, same present-beats-absent
   *  contract `LabeledPort`'s slots use. */
  actions?: ReactNode;
  /** Footer links — VS Code's View Problem / Quick Fix row. */
  footer?: ReactNode;
  className?: string;
  style?: CSSProperties;
}

// WHY lucide-react is imported DIRECTLY here rather than through
// `./glyph`'s resolver-context pattern (§7's stock-parts table names "via
// Glyph"): `glyph.tsx` imports `@bbox-ui/glyph-content`, `private: true`
// and unpublished — the same blocker class CLAUDE.md already names for the
// two canvas adapters, and the exact reason `glyph.tsx` itself is
// deliberately NOT a registry item. `DiagnosticFlag` IS meant to ship as a
// registry item (this axis's one new interactive component), and this
// kit's registry items never take a `registryDependency` on each other —
// so it cannot depend on a component that cannot itself be installed.
// `dropdown-menu.tsx` already sets the precedent of importing lucide-react
// icons straight from the package for exactly this reason.
export function DiagnosticFlag({ diagnostics, actions, footer, className, style }: DiagnosticFlagProps) {
  const severity = maxDiagnosticSeverity(diagnostics) ?? "info";
  const Icon = SEVERITY_ICON[severity];
  const color = diagnosticColorVar(severity);
  const count = diagnostics.length;

  return (
    <Popover>
      <PopoverTrigger
        render={
          <button
            type="button"
            data-slot="diagnostic-flag"
            data-severity={severity}
            data-count={count > 1 ? count : undefined}
            aria-label={`${count} ${severity} diagnostic${count === 1 ? "" : "s"}`}
            className={cn(
              "relative inline-flex shrink-0 cursor-pointer items-center justify-center rounded-full border-2",
              className,
            )}
            style={{
              width: DIAGNOSTIC_FLAG_SIZE_PX,
              height: DIAGNOSTIC_FLAG_SIZE_PX,
              background: "var(--card)",
              borderColor: color,
              color,
              ...style,
            }}
          >
            <Icon aria-hidden style={{ width: "70%", height: "70%" }} />
            {/* The badge's own COUNT (Appendix B item 3 / convergence
                table: Vyuh's status badges, maxGraph's
                `containsValidationErrors`) — the one piece of chrome a
                scalar `diagnostic` could never have rendered, and the
                deciding reason §1 was amended to a list. One finding = no
                count, same read as today's single-mark design. */}
            {count > 1 && (
              <span
                data-slot="diagnostic-flag-count"
                aria-hidden
                className="absolute -bottom-1 -right-1 inline-flex min-w-[14px] items-center justify-center rounded-full px-[3px] text-[9px] leading-[14px] font-semibold text-white"
                style={{ background: color }}
              >
                {count}
              </span>
            )}
          </button>
        }
      />
      {/* Click: the full anatomy — message · code chip · host actions ·
          host footer, one block per diagnostic (VS Code's own hover, which
          is Zach's reference screenshot). */}
      <PopoverContent data-slot="diagnostic-flag-content">
        <div className="flex flex-col gap-2">
          {diagnostics.map((d) => (
            <div key={d.id} className="flex items-center gap-1.5">
              <span style={{ color: diagnosticColorVar(d.severity) }}>{d.message ?? d.severity}</span>
              {d.code ? (
                <Badge variant="outline" size="sm">
                  {d.code}
                </Badge>
              ) : null}
            </div>
          ))}
        </div>
        {actions ? (
          <div data-slot="diagnostic-flag-actions" className="mt-2 flex gap-2">
            {actions}
          </div>
        ) : null}
        {footer ? (
          <div data-slot="diagnostic-flag-footer" className="mt-2 flex gap-3 text-xs text-muted-foreground">
            {footer}
          </div>
        ) : null}
      </PopoverContent>
    </Popover>
  );
}

// src/components/paintOrder.ts — the paint-order ladder (Card 04, the
// z-order lane of docs/provenance/z-order.md's wave).
//
// THE RULING THIS FILE IMPLEMENTS (full text: the z-order lane brief) —
// "the line is the box, not the node." The mechanical test: can the
// answer be computed from ONE component's own props, knowing nothing
// about what else is on the canvas and nothing about what the pointer is
// doing?
//   - Yes → paint order. Deterministic from the component's own tree,
//     identical on every host, required for the render to be correct AT
//     ALL. That is layout, it is portable, and it lives HERE, named.
//   - Needs the selection, the pointer, or a sibling node's identity →
//     canvas z-order. Host-owned. Never travels, never lives here.
//
// THIS IS A REFACTOR, NOT A FEATURE, for five of these nine tiers: the
// kit already emitted raw numeric `zIndex` literals before this file
// existed, ad hoc, coordinated only by prose comments across three
// files. Replacing them with named tokens below is defined to be a
// NO-OP — every one of the five reproduces its pre-existing literal
// exactly, verified by a captured getComputedStyle before/after on the
// same mounted stories (src/components/PaintOrder.stories.tsx,
// "TokensReproduceTodaysNumbers"; the raw numbers are recorded in
// docs/provenance/z-order.md). Only `headerChrome` is new — the nesting
// tier Zach actually asked for (a Block's header/footer must paint above
// its own `BlockMembers` region, however deeply that region nests other
// Blocks inside it).
//
// THE ISOLATION INVARIANT is what makes a closed, per-tier integer scale
// safe to reuse across files that never coordinate with each other:
// every component root that emits a tier below sets `isolation: isolate`
// (see block.tsx's root, blockPort.tsx's `[data-slot="block-port"]`
// root, portEdge.tsx's `[data-slot="port-edge"]` root). A CSS stacking
// context is a hard wall — a descendant's z-index cannot outrank
// anything outside its isolated root no matter what integer it carries.
// That is what lets `portDot` and `flagBadge` share the raw value `1`
// without ever actually competing: they live in different isolated
// roots and are never compared in the same stacking context. It is also
// what makes `headerChrome` beat an arbitrarily deep nested Block's own
// highest tier: the nested Block, however many levels deep, is trapped
// inside its OWN isolated root, so it contributes only its own
// (z-index:auto, i.e. stack level 0) box to its parent's stacking order
// — never its interior maximum. Remove the invariant from one nested
// root and this reasoning breaks; `PaintOrder.stories.tsx`'s
// `NestedChildStaysBehindHeader` story is the measured proof, and a
// mutation test (temporarily deleting one `isolation: isolate`) is
// recorded as having actually turned it red in docs/provenance/z-order.md.
//
// The kit NEVER emits a z-index on a node ROOT (a Block's own outer box,
// a BlockPort wrapper's own outer box) — only on things INSIDE one. A
// host's canvas z-order (raise-on-select, drag-to-front, Vyuh
// Flow's `child.z = parent.z + 1`) stays exactly that: host-owned,
// never emitted here.

/**
 * The closed, ordered ladder — ascending: earlier names paint further
 * back, later names paint on top, WITHIN one isolated component root.
 * "Ordered" is a design narrative connecting the tiers to what they
 * paint, not a claim that every numeric value is globally monotonic —
 * the isolation invariant above is what actually keeps unrelated tiers
 * (e.g. `portDot` and `flagBadge`, both `1`, in different files) from
 * ever needing to out-rank each other; see `PAINT_TIER_VALUE`'s own
 * per-entry comments for exactly which existing call site each number
 * reproduces.
 */
export const PAINT_TIER_ORDER = [
  "surface",
  "memberContent",
  "memberOverflow",
  "wire",
  "headerChrome",
  "portDot",
  "flagBadge",
  "laneOverlay",
  "dragActive",
  "diagnosticHalo",
] as const;

export type PaintTierName = (typeof PAINT_TIER_ORDER)[number];

/**
 * One frozen value per tier. Every entry that reproduces a pre-existing
 * raw literal says so and names its call site; the two new entries
 * (`headerChrome`, and the currently-unwired placeholders) say that too.
 */
const PAINT_TIER_VALUE: Readonly<Record<PaintTierName, number>> = Object.freeze({
  // Placeholder — not wired to any raw zIndex today. Lowest in the
  // ladder: a surface/inset background paints under its own box's
  // content.
  surface: 0,
  // portEdge.tsx:846 (`FreeSlotCard`) — the RESTING (non-dragging) value
  // of `zIndex: isDragging ? 10 : 1`. A free-mode draggable card is
  // exactly "content within the box".
  memberContent: 1,
  // Placeholder — not wired today. Content that bleeds past its own
  // slot but stays inside the parent box (e.g. a future overflowing
  // member preview).
  memberOverflow: 1,
  // Placeholder — not wired today. A connector line drawn within one
  // component's own box (distinct from `Trace`/cross-canvas wires,
  // which are host-composed and out of scope for a single box's ladder).
  wire: 1,
  // NEW — block.tsx's `block-header` / `block-footer`. Not a
  // pre-existing literal: today those two slots are non-positioned and
  // structurally lose to ANY positioned sibling (including a
  // `position: relative` `BlockMembers` region with z-index:auto),
  // which is exactly backwards for nesting. `headerChrome` is what a
  // Block's own chrome needs to beat its own members region — see this
  // file's header comment and `PaintOrder.stories.tsx`'s
  // `NestedChildStaysBehindHeader`.
  headerChrome: 2,
  // blockPort.tsx:412 (`BlockFunctionPort`) and blockPort.tsx:538
  // (`BlockPortRail`'s wrapper) — both were `zIndex: 1`. A port's own
  // dot, whether the header's reserved function port or a rail item,
  // needs to sit above the Block it decorates (BlockPort.stories.tsx's
  // own `StackingAboveBlock`) — including above the Block's OWN
  // `headerChrome`, since the function port is literally the header's
  // pin. That relationship holds without portDot needing to outrank
  // headerChrome numerically: the whole `<Block>` is a SIBLING of the
  // rail/function-port divs inside `BlockPort`'s own isolated
  // `[data-slot="block-port"]` root, not a descendant of them, so the
  // comparison that actually matters is portDot's explicit positive
  // z-index vs. the whole (isolation-capped) Block's stack level 0 —
  // see this file's header comment.
  portDot: 1,
  // block.tsx:334 (`block-diagnostic-flag`) — was `zIndex: 1`. The
  // corner diagnostic badge.
  flagBadge: 1,
  // portEdge.tsx:1003 (`PortLaneOverlay`) — was `zIndex: 5`. The
  // floating multi-line lane editor.
  laneOverlay: 5,
  // portEdge.tsx:846 (`FreeSlotCard`) — the DRAGGING value of
  // `zIndex: isDragging ? 10 : 1`. Explicitly named, per the brief's own
  // instruction, so the one place a gesture leaks into paint order is
  // visible and reviewable rather than inline.
  dragActive: 10,
  // Placeholder — not wired today. Block's own halo highlighter
  // (`highlighterKind="halo"`) is a `boxShadow`, which needs no z-index
  // at all; this tier exists so a future halo-as-overlay implementation
  // has a named slot at the top of the ladder without inventing a
  // number.
  diagnosticHalo: 1,
});

/** Look up one tier's frozen z-index value. The only way any component
 *  in `src/components` may produce a `zIndex` — see
 *  `paintOrder.test.ts`'s grep guard, which fails on any raw numeric
 *  `zIndex` literal surviving in this directory. */
export function paintTier(name: PaintTierName): number {
  return PAINT_TIER_VALUE[name];
}

/**
 * The one structural half of the ruling: every component root that
 * emits any tier above must set this. Spread onto that root's `style`.
 * Kept as a named export (rather than callers writing the literal
 * object) so `PaintOrder.stories.tsx` can assert every emitting root
 * used exactly this, not a hand-rolled equivalent.
 */
export const ISOLATED_ROOT_STYLE = { isolation: "isolate" } as const;

// src/components/popover.tsx — based on the stock shadcn `new-york` Popover
// (apps/docs/src/registry/new-york-v4/ui/popover.tsx, over Base UI's
// `@base-ui/react/popover`), NOT copied verbatim: that stock copy only ever
// positions against its own trigger, and this kit needs a popover that can
// hang off a point on the canvas that has no DOM element at all (the
// font-size popover in docs/menus/screenshots/03-font-size-popover.png opens
// off the selection, not off a button). `PopoverPositioner.Props` already
// accepts `anchor: Element | VirtualElement | ...` (verified against
// apps/storybook-basics/node_modules/@base-ui/react/internals/
// useAnchorPositioning.d.ts) — the stock copy's `Pick` just never asked for
// it. `container` and `collisionPadding` are exposed for the same reason:
// they're the two other host-contract knobs docs/menus/MENU-KIT-DESIGN.md
// §4 names ("container? — portal target inside the host's token scope",
// "collisionPadding" for the boundary a canvas-anchored popup must respect).
"use client";

import { Popover as PopoverPrimitive } from "@base-ui/react/popover";

import { cn } from "../lib/utils";

function Popover({ ...props }: PopoverPrimitive.Root.Props) {
  return <PopoverPrimitive.Root data-slot="popover" {...props} />;
}

function PopoverTrigger({ ...props }: PopoverPrimitive.Trigger.Props) {
  return <PopoverPrimitive.Trigger data-slot="popover-trigger" {...props} />;
}

export interface PopoverContentProps
  extends PopoverPrimitive.Popup.Props,
    Pick<
      PopoverPrimitive.Positioner.Props,
      "align" | "alignOffset" | "side" | "sideOffset" | "anchor" | "collisionPadding"
    > {
  /** WHY: portal target inside the host's own token/theme scope (the kit's
      universal host contract, MENU-KIT-DESIGN.md §4) — `undefined` keeps
      Base UI's own default of `document.body`, which is fine for a host
      with no scoped root. */
  container?: PopoverPrimitive.Portal.Props["container"];
  /** WHY (ported concept, menuLabModel.ts's `popoverMode`): a live text
      editor open elsewhere on the surface (an inline rename field, a
      color-hex input) must keep its OWN focus while this popover is open —
      the default "move focus into the popup on open" would steal the caret
      mid-keystroke. Maps to Base UI Popup's `initialFocus`, narrowed to a
      boolean because the kit only ever needs "move focus" vs "leave it
      alone," never `initialFocus`'s ref/interaction-type callback forms.
      Default `true` (Base UI's own default); pill/editing surfaces pass
      `false`. */
  autoFocus?: boolean;
}

function PopoverContent({
  className,
  align = "center",
  alignOffset = 0,
  side = "bottom",
  sideOffset = 4,
  anchor,
  collisionPadding,
  container,
  autoFocus = true,
  ...props
}: PopoverContentProps) {
  return (
    <PopoverPrimitive.Portal container={container}>
      <PopoverPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        anchor={anchor}
        collisionPadding={collisionPadding}
        className="isolate z-50 outline-none"
      >
        <PopoverPrimitive.Popup
          data-slot="popover-content"
          initialFocus={autoFocus}
          className={cn(
            "data-open:animate-in data-closed:animate-out data-closed:fade-out-0 data-open:fade-in-0 data-closed:zoom-out-95 data-open:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 ring-foreground/10 bg-popover text-popover-foreground flex flex-col gap-2.5 rounded-lg p-2.5 text-sm shadow-md ring-1 duration-100 data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2 z-50 w-72 origin-(--transform-origin) outline-hidden",
            className,
          )}
          {...props}
        />
      </PopoverPrimitive.Positioner>
    </PopoverPrimitive.Portal>
  );
}

export { Popover, PopoverContent, PopoverTrigger };

// src/components/tooltip.tsx — copied verbatim from
// apps/docs/src/registry/new-york-v4/ui/tooltip.tsx (the stock shadcn
// `new-york` Tooltip over Base UI's Tooltip primitive). packages/inspector
// also has a tooltip.tsx, but it's coupled to the dock's own portal
// container and z-index stack (`dockPortalContainer()`, `z-[320]`) — plumbing
// this standalone app doesn't have, so the docs version is the cleaner,
// self-contained pick. Only the `cn` import path changed to match this
// app's own src/lib/utils.ts.
"use client";

import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip";

import { cn } from "../lib/utils";

function TooltipProvider({ delay = 0, ...props }: TooltipPrimitive.Provider.Props) {
  return <TooltipPrimitive.Provider data-slot="tooltip-provider" delay={delay} {...props} />;
}

function Tooltip({ ...props }: TooltipPrimitive.Root.Props) {
  return <TooltipPrimitive.Root data-slot="tooltip" {...props} />;
}

function TooltipTrigger({ ...props }: TooltipPrimitive.Trigger.Props) {
  return <TooltipPrimitive.Trigger data-slot="tooltip-trigger" {...props} />;
}

function TooltipContent({
  className,
  side = "top",
  sideOffset = 4,
  align = "center",
  alignOffset = 0,
  anchor,
  collisionPadding,
  container,
  children,
  style,
  ...props
}: TooltipPrimitive.Popup.Props &
  // WHY `anchor` was added to this Pick (2026-09-18, menu kit build): same
  // reason as dropdown-menu.tsx's matching edit — a canvas-anchored hint (a
  // pointer-position tooltip with no DOM trigger) needs Positioner's own
  // `anchor` (a Floating UI VirtualElement), which this Pick never
  // surfaced. Adds-only; every current consumer that omits `anchor` is
  // unaffected.
  //
  // `collisionPadding` and `container` followed in the same pass that fixed
  // dropdown-menu.tsx — see the longer note there. The pair has to stay in
  // lockstep across these two files: a host that scopes its design tokens
  // to a container element and gets themed MENUS but unthemed TOOLTIPS has
  // a bug that is much harder to read than one where neither works.
  Pick<
    TooltipPrimitive.Positioner.Props,
    "align" | "alignOffset" | "side" | "sideOffset" | "anchor" | "collisionPadding"
  > &
  Pick<TooltipPrimitive.Portal.Props, "container">) {
  return (
    <TooltipPrimitive.Portal container={container}>
      <TooltipPrimitive.Positioner
        align={align}
        alignOffset={alignOffset}
        side={side}
        sideOffset={sideOffset}
        anchor={anchor}
        collisionPadding={collisionPadding}
        className="isolate z-50"
      >
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          className={cn(
            "data-open:animate-in data-open:fade-in-0 data-open:zoom-in-95 data-[state=delayed-open]:animate-in data-[state=delayed-open]:fade-in-0 data-[state=delayed-open]:zoom-in-95 data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 inline-flex items-center gap-1.5 px-3 py-1.5 text-xs has-data-[slot=kbd]:pr-1.5 **:data-[slot=kbd]:relative **:data-[slot=kbd]:isolate **:data-[slot=kbd]:z-50 **:data-[slot=kbd]:rounded-sm data-[side=inline-start]:slide-in-from-right-2 data-[side=inline-end]:slide-in-from-left-2 z-50 w-fit max-w-xs origin-(--transform-origin) bg-foreground text-background",
            className,
          )}
          // The skin seam (src/skin/skin.ts + skin.css) — `rounded-md`
          // moved off the class list above and onto here so a skin can
          // reach it; `var(--radius-md)` is exactly what it resolved to,
          // so a consumer who never imports skin.css is byte-identical.
          style={{ borderRadius: "var(--bbox-skin-radius, var(--radius-md))", ...style }}
          {...props}
        >
          {children}
          <TooltipPrimitive.Arrow className="size-2.5 translate-y-[calc(-50%-2px)] rotate-45 rounded-[2px] data-[side=inline-end]:top-1/2! data-[side=inline-end]:-left-1 data-[side=inline-end]:-translate-y-1/2 data-[side=inline-start]:top-1/2! data-[side=inline-start]:-right-1 data-[side=inline-start]:-translate-y-1/2 z-50 bg-foreground fill-foreground data-[side=bottom]:top-1 data-[side=left]:top-1/2! data-[side=left]:-right-1 data-[side=left]:-translate-y-1/2 data-[side=right]:top-1/2! data-[side=right]:-left-1 data-[side=right]:-translate-y-1/2 data-[side=top]:-bottom-2.5" />
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  );
}

export { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger };

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

// src/skin/regionVariants.ts — TEN DRAWINGS of the one Region component,
// as a typed spec and one attribute. The contract the dispatcher spelled
// out in docs/ASK-2026-09-19-PORTS-EDGES-REGIONS-FEEDBACK.md ("Contracts"),
// owned by lane `regions`:
//
//   • `REGION_VARIANTS: Record<RegionVariantId, RegionVariant>`, ids
//     `v1`..`v10`, `v1` the default so ignoring is free. `v1`-`v5` are the
//     original five; `v6`-`v8` are the three Zach picked out of the
//     2026-09-19 babble gallery; `v9`-`v10` are the two asks of 2026-09-20
//     00:45. Every one is ADDED, never substituted, because he is still
//     comparing them against each other (see each block).
//   • The variant in force is read from `data-bbox-region-variant` — on
//     `document.documentElement` for an app (`dataset.bboxRegionVariant`),
//     or on ANY nearer ancestor for a gallery that shows several at once.
//     No React context: the paint is CSS custom properties keyed on that
//     attribute (`regionVariants.css`, the same mechanism `skin.css` uses),
//     and the two numbers CSS cannot drive — the arm header's height,
//     which `regionLayout` needs, and the fold chevron's reveal, which is a
//     prop — come from THIS file, keyed on the same attribute
//     (`readRegionVariant`). So an app switch is three lines
//     (`setRegionVariant`), and a Storybook global is a wrapper stamped
//     with `regionVariantAttrs`.
//
// WHAT EVERY VARIANT KEEPS (Zach, 2026-09-19, measured by
// `RegionVariants.stories.tsx` per variant): the corner block flush with
// the frame's top-left; its port dots ON the frame edge, never clipped
// ("I want the port to be right on the edge. and it shouldn't be cut off
// by the frame"); arms stacked under the corner and folded by the chevron;
// the For Loop reading he liked (`Pasted image 20260919115424.png`); and
// the opaque card, which is the host's own `Block` and deliberately NOT a
// variant axis. What varies: the frame's stroke/fill/radius/open sides,
// how the corner block joins the frame, how an arm header is marked, the
// nested-region contrast, and the arm title's type.
//
// WHY the numbers live here and the paint lives in CSS, rather than
// everything in one place: `regionLayout` is a PURE twin that hosts read
// without rendering (a tldraw shape's geometry, an SVG export), so the
// header height has to be a plain number a host can pass in — a computed
// style is not available to a function that never touched the DOM. The
// paint, by contrast, wants to follow light/dark and skin without a
// re-render, which is what custom properties are for. The story's item 3
// (measured header height === `arms.headerPx`) is what keeps the two from
// drifting.
//
// NO DASHED FRAME: `frame.dash` exists in the contract's shape and is left
// undefined on all eight on purpose — the dashed `ss-region` placeholder in
// `Pasted image 20260919114919.png` is part of what Zach called "very
// unprofessional", so a dashed proposal would be proposing the complaint.

export const REGION_VARIANT_IDS = ["v1", "v2", "v3", "v4", "v5", "v6", "v7", "v8", "v9", "v10"] as const;
export type RegionVariantId = (typeof REGION_VARIANT_IDS)[number];

export const DEFAULT_REGION_VARIANT: RegionVariantId = "v1";

/** The attribute a host stamps — on `<html>` for an app, or on any
 *  ancestor for one board / one gallery row. */
export const REGION_VARIANT_ATTR = "data-bbox-region-variant";
/** The same attribute as `HTMLElement.dataset` spells it. */
export const REGION_VARIANT_DATASET_KEY = "bboxRegionVariant";

export interface RegionVariant {
  id: RegionVariantId;
  title: string;
  /** One line for a picker or a gallery caption. */
  blurb: string;
  frame: {
    /** CSS colour (a theme token, never a literal — skin and dark follow). */
    stroke: string;
    fill: string;
    /** The shared top-left radius — the corner card's too. LOAD-BEARING, not
     *  documentation: `"0px"` is how a drawing declares itself SQUARE, and the
     *  two junction tests read it as their oracle (`RegionVariants.stories.tsx`'s
     *  `CornerMeetsFrameSquare`, `variants.smoke.test.tsx`'s (e)). A value here
     *  that disagrees with `regionVariants.css` is a failure, which is what
     *  keeps the spec and the paint from drifting. */
    radius: string;
    /** Never set on the five shipped (see this file's header). */
    dash?: "dashed";
    /** The bracket: no right and no bottom line. */
    open?: "right-bottom";
  };
  corner: {
    /** `flush`: the card's border sits on the frame's line (the Labeled
     *  Group Node look, `blockRegion.tsx`'s header). `ruled`: flush, AND the
     *  card's bottom edge continues as a full-width rule under it — the
     *  line Zach pointed at in `Pasted image 20260919115353.png` and again
     *  in `…20260920004250.png`'s DESIRED half. `band`: ruled, AND the card
     *  is meant to span the region's whole width with its title centred in
     *  it (`…20260920004529.png`) — the header IS the band.
     *
     *  WHY `band` still says `ruled`'s rule rather than replacing the card:
     *  Zach, 2026-09-20 — "its just the block is stretch accross the entire
     *  width of the region". The corner card is not removed and no port
     *  moves; its dots are already on its own left edge, which at full width
     *  IS the region's left edge. What a DRAWING can reach is the rule, the
     *  square corners and the centred title; the card's WIDTH is never a
     *  drawing's. A host sets it (a `width` prop in `hosts/nodeViews.tsx`, a
     *  persisted `props.w` in the app's `shapes/region/cornerBlock.ts`), or,
     *  for a title-only corner, `BlockRegion` hugs the title itself
     *  (`blockRegion.tsx`'s `TitleCorner`). No `--bbox-region-*` token
     *  reaches it — see `block.tsx`'s `BlockShape`. */
    integration: "flush" | "ruled" | "band";
    /** The card's ONE free corner, bottom-right. Absent = the frame's shared
     *  radius, which is what the drawing Zach approved does. `"square"` is
     *  `v2`'s own trick — a full-width rule leaves a square corner cleanly
     *  instead of departing from a curve. NOT implied by `ruled`: `v9` is
     *  ruled and keeps the curve, because that is what he drew. */
    freeCorner?: "square";
  };
  arms: {
    /** How an arm's header row is marked. The contract named
     *  `rule | band | none`; `indent` (a code-style guide) and `card` (an
     *  inset card) are this lane's two additions, each a whole drawing.
     *  `outline` and `edge` came out of the 2026-09-19 babble gallery
     *  (`reports/media/branch-arm-drawings-2026-09-19.html`), where Zach
     *  picked three of five: `outline` is `card` with the fill taken out,
     *  `edge` is that outline run to the frame's own side lines, and his
     *  third pick needs no new kind at all — it is `none` (see `v8`). */
    header: "none" | "rule" | "band" | "indent" | "card" | "outline" | "edge";
    /** A hairline between consecutive rows (never above the first). */
    divider: boolean;
    /** The header row's height, px — fed to `regionLayout`. */
    headerPx: number;
    /** `FoldingChevron`'s own `reveal` prop. `hover` still shows a FOLDED
     *  arm's chevron always (that rule is the component's, not ours). */
    chevron: "always" | "hover";
  };
  nested: {
    /** `deepen`: a region inside a region fills one tone deeper. */
    contrast: "none" | "deepen";
  };
  opaque: {
    /** Always `stock`: the P5 card is the host's `Block`, unchanged. */
    card: "stock";
  };
}

